INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (36,50,2,'{\"post\":{\"id\":50,\"academic_year_id\":1,\"title\":\"Ninoy Aquino Day\",\"slug\":\"ninoy-aquino-day\",\"excerpt\":\"Sa paggunita natin sa Ninoy Aquino Day, ating binabalikan ang isang mahalagang bahagi ng kasaysayan ng Pilipinas ang tapang ng isang Pilipinong piniling ipaglaban ang kalayaan at demokrasya sa kabila ng panganib.\",\"content\":\"Sa paggunita natin sa Ninoy Aquino Day, ating binabalikan ang isang mahalagang bahagi ng kasaysayan ng Pilipinas ang tapang ng isang Pilipinong piniling ipaglaban ang kalayaan at demokrasya sa kabila ng panganib.\\r\\n\\r\\nAng buhay at sakripisyo ni Ninoy Aquino ay naging simbolo ng paninindigan para sa bayan. Ang kanyang pagkamatay ay hindi nagtapos sa kanyang laban; sa halip, nagmulat ito sa maraming Pilipino at nagbigay-lakas sa sambayanang manindigan para sa pagbabago, katarungan, at kalayaan.\\r\\n\\r\\nHigit sa pag-alala sa isang tao, ang araw na ito ay paalala sa kapangyarihan ng pagkakaisa. Ipinakita ng kasaysayan na kapag nagkaisa ang mga Pilipino at hindi natatakot ipahayag ang kanilang tinig, may kakayahan tayong harapin ang anumang hamon at ipaglaban ang nararapat.\\r\\n\\r\\nNawa’y magsilbing inspirasyon ang kanyang sakripisyo sa bawat Pilipino upang maging mapanindigan, makialam sa mga usaping panlipunan, at gamitin ang ating kalayaan nang may pananagutan.\\r\\n\\r\\nSa araw na ito, ating alalahanin si Ninoy Aquino hindi lamang bilang isang bayani ng nakaraan, kundi bilang paalala na ang tunay na pagmamahal sa bayan ay nakikita sa tapang na manindigan, sa malasakit sa kapwa, at sa patuloy na pag-asa para sa isang mas makatarungan at malayang Pilipinas.\\r\\n\\r\\nkatha ni P. E. Baustista\\r\\n\\r\\n#DMMMSUNLUC\\r\\n#nluccsbo\",\"category\":\"nluc\",\"label\":\"NLUC\",\"image\":null,\"is_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-21 13:22:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:15:26\",\"updated_at\":\"2026-08-24 16:15:26\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":15,\"post_id\":50,\"file_path\":\"uploads/posts/post_50_966abd181f98cd2f.jpg\",\"original_name\":\"781053443_1501952355282785_7552588831754086645_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-08-24 16:15:26\"}]}','Snapshot before edit',1,'2026-09-01 12:49:02');
