INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (52,44,4,'{\"post\":{\"id\":44,\"academic_year_id\":1,\"title\":\"📢 𝐀𝐍𝐍𝐎𝐔𝐍𝐂𝐄𝐌𝐄𝐍𝐓 | 𝐑𝐄𝐒𝐂𝐇𝐄𝐃𝐔𝐋𝐈𝐍𝐆 𝐎𝐅 𝐌𝐈𝐃𝐓𝐄𝐑𝐌 𝐄𝐗𝐀𝐌𝐈𝐍𝐀𝐓𝐈𝐎𝐍𝐒\",\"slug\":\"publication-6\",\"excerpt\":\"Due to the disruption of classes brought about by the prevailing weather conditions, the schedule of the 𝐌𝐢𝐝𝐭𝐞𝐫𝐦 𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧𝐬 has been 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 to provide students and faculty with sufficient time to prepare and to ensure that academic activities can proceed in an orderly manner.\",\"content\":\"Due to the disruption of classes brought about by the prevailing weather conditions, the schedule of the 𝐌𝐢𝐝𝐭𝐞𝐫𝐦 𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧𝐬 has been 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 to provide students and faculty with sufficient time to prepare and to ensure that academic activities can proceed in an orderly manner.\\r\\nAs per the 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 𝐞𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧 𝐝𝐚𝐭𝐞𝐬 𝐬𝐮𝐛𝐦𝐢𝐭𝐭𝐞𝐝 𝐛𝐲 𝐭𝐡𝐞 𝐎𝐟𝐟𝐢𝐜𝐞 𝐨𝐟 𝐭𝐡𝐞 𝐕𝐢𝐜𝐞 𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭 𝐟𝐨𝐫 𝐀𝐜𝐚𝐝𝐞𝐦𝐢𝐜 𝐀𝐟𝐟𝐚𝐢𝐫𝐬 (𝐎𝐕𝐏𝐀𝐀), the Midterm Examinations will now be conducted on 𝐀𝐮𝐠𝐮𝐬𝐭 18–20, 2026.\\r\\nWith this adjustment, everyone is advised to disregard the previously issued memorandum regarding the Midterm Examination schedule, as the dates indicated therein have been superseded by the newly rectified schedule.\\r\\nWe encourage everyone to take note of the new dates and make the necessary adjustments to your study plans, schedules, and other preparations. Kindly stay updated for any succeeding announcements regarding the detailed examination schedule and other relevant instructions.\",\"category\":\"sluc\",\"label\":\"SLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-07 21:12:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:05:35\",\"updated_at\":\"2026-08-24 16:05:35\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":9,\"post_id\":44,\"file_path\":\"uploads/posts/post_44_433002f0696cc9ff.jpg\",\"original_name\":\"767430925_1354384186904620_936484165768812276_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-08-24 16:05:35\"}]}','Snapshot before edit',6,'2026-09-01 13:11:56');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (53,44,5,'{\"post\":{\"id\":44,\"academic_year_id\":1,\"title\":\"📢 𝐀𝐍𝐍𝐎𝐔𝐍𝐂𝐄𝐌𝐄𝐍𝐓 | 𝐑𝐄𝐒𝐂𝐇𝐄𝐃𝐔𝐋𝐈𝐍𝐆 𝐎𝐅 𝐌𝐈𝐃𝐓𝐄𝐑𝐌 𝐄𝐗𝐀𝐌𝐈𝐍𝐀𝐓𝐈𝐎𝐍𝐒\",\"slug\":\"publication-6\",\"excerpt\":\"Due to the disruption of classes brought about by the prevailing weather conditions, the schedule of the 𝐌𝐢𝐝𝐭𝐞𝐫𝐦 𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧𝐬 has been 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 to provide students and faculty with sufficient time to prepare and to ensure that academic activities can proceed in an orderly manner.\",\"content\":\"Due to the disruption of classes brought about by the prevailing weather conditions, the schedule of the 𝐌𝐢𝐝𝐭𝐞𝐫𝐦 𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧𝐬 has been 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 to provide students and faculty with sufficient time to prepare and to ensure that academic activities can proceed in an orderly manner.\\r\\nAs per the 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 𝐞𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧 𝐝𝐚𝐭𝐞𝐬 𝐬𝐮𝐛𝐦𝐢𝐭𝐭𝐞𝐝 𝐛𝐲 𝐭𝐡𝐞 𝐎𝐟𝐟𝐢𝐜𝐞 𝐨𝐟 𝐭𝐡𝐞 𝐕𝐢𝐜𝐞 𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭 𝐟𝐨𝐫 𝐀𝐜𝐚𝐝𝐞𝐦𝐢𝐜 𝐀𝐟𝐟𝐚𝐢𝐫𝐬 (𝐎𝐕𝐏𝐀𝐀), the Midterm Examinations will now be conducted on 𝐀𝐮𝐠𝐮𝐬𝐭 18–20, 2026.\\r\\nWith this adjustment, everyone is advised to disregard the previously issued memorandum regarding the Midterm Examination schedule, as the dates indicated therein have been superseded by the newly rectified schedule.\\r\\nWe encourage everyone to take note of the new dates and make the necessary adjustments to your study plans, schedules, and other preparations. Kindly stay updated for any succeeding announcements regarding the detailed examination schedule and other relevant instructions.\",\"category\":\"sluc\",\"label\":\"SLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-07 21:12:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":6,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:05:35\",\"updated_at\":\"2026-09-01 13:11:56\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":9,\"post_id\":44,\"file_path\":\"uploads/posts/post_44_433002f0696cc9ff.jpg\",\"original_name\":\"767430925_1354384186904620_936484165768812276_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-08-24 16:05:35\"}]}','Saved publication',6,'2026-09-01 13:11:57');
