INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (55,51,11,'{\"post\":{\"id\":51,\"academic_year_id\":1,\"title\":\"EXAM MODE: ON!\",\"slug\":\"exam-mode-on\",\"excerpt\":\"Isang ballpen, isang scratch, isang reviewer… at isang taong biglang nag-message ng “Good luck, love!” sana ol!\\r\\nHindi man kumpleto ang tulog, basta kumpleto ang gamit.\\r\\nHindi man handa ang utak, basta handa ang puso.\\r\\nAt kung wala talagang masagot sa exam—“Lord, ikaw na bahala.” 🙏😭\\r\\nPAPASA AKO! PAPASA KA! PAPASA TAYO!\\r\\nIpapasa ko para sa’yo. Ipapasa mo para sa’kin. Ipasa natin ’to, mga beh! 📖\\r\\nGood luck, NLUCians!\\r\\n#DMMMSUNLUC \\r\\n#nluccsbo\",\"content\":\"Isang ballpen, isang scratch, isang reviewer… at isang taong biglang nag-message ng “Good luck, love!” sana ol!\\r\\nHindi man kumpleto ang tulog, basta kumpleto ang gamit.\\r\\nHindi man handa ang utak, basta handa ang puso.\\r\\nAt kung wala talagang masagot sa exam—“Lord, ikaw na bahala.” 🙏😭\\r\\nPAPASA AKO! PAPASA KA! PAPASA TAYO!\\r\\nIpapasa ko para sa’yo. Ipapasa mo para sa’kin. Ipasa natin ’to, mga beh! 📖\\r\\nGood luck, NLUCians!\\r\\n#DMMMSUNLUC \\r\\n#nluccsbo\",\"category\":\"nluc\",\"label\":\"NLUC\",\"image\":null,\"is_featured\":1,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-23 22:17:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:18:05\",\"updated_at\":\"2026-09-01 13:51:03\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":17,\"post_id\":51,\"file_path\":\"uploads/posts/post_51_478548640c720999.jpg\",\"original_name\":\"784664975_1504026565075364_2903386929420344111_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:51:03\"}]}','Saved publication',1,'2026-09-01 13:51:03');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (56,50,10,'{\"post\":{\"id\":50,\"academic_year_id\":1,\"title\":\"Ninoy Aquino Day\",\"slug\":\"ninoy-aquino-day\",\"excerpt\":\"Sa paggunita natin sa Ninoy Aquino Day, ating binabalikan ang isang mahalagang bahagi ng kasaysayan ng Pilipinas ang tapang ng isang Pilipinong piniling ipaglaban ang kalayaan at demokrasya sa kabila ng panganib.\",\"content\":\"Sa paggunita natin sa Ninoy Aquino Day, ating binabalikan ang isang mahalagang bahagi ng kasaysayan ng Pilipinas ang tapang ng isang Pilipinong piniling ipaglaban ang kalayaan at demokrasya sa kabila ng panganib.\\r\\n\\r\\nAng buhay at sakripisyo ni Ninoy Aquino ay naging simbolo ng paninindigan para sa bayan. Ang kanyang pagkamatay ay hindi nagtapos sa kanyang laban; sa halip, nagmulat ito sa maraming Pilipino at nagbigay-lakas sa sambayanang manindigan para sa pagbabago, katarungan, at kalayaan.\\r\\n\\r\\nHigit sa pag-alala sa isang tao, ang araw na ito ay paalala sa kapangyarihan ng pagkakaisa. Ipinakita ng kasaysayan na kapag nagkaisa ang mga Pilipino at hindi natatakot ipahayag ang kanilang tinig, may kakayahan tayong harapin ang anumang hamon at ipaglaban ang nararapat.\\r\\n\\r\\nNawa’y magsilbing inspirasyon ang kanyang sakripisyo sa bawat Pilipino upang maging mapanindigan, makialam sa mga usaping panlipunan, at gamitin ang ating kalayaan nang may pananagutan.\\r\\n\\r\\nSa araw na ito, ating alalahanin si Ninoy Aquino hindi lamang bilang isang bayani ng nakaraan, kundi bilang paalala na ang tunay na pagmamahal sa bayan ay nakikita sa tapang na manindigan, sa malasakit sa kapwa, at sa patuloy na pag-asa para sa isang mas makatarungan at malayang Pilipinas.\\r\\n\\r\\nkatha ni P. E. Baustista\\r\\n\\r\\n#DMMMSUNLUC\\r\\n#nluccsbo\",\"category\":\"usc\",\"label\":\"NLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-21 13:22:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:15:26\",\"updated_at\":\"2026-09-01 13:06:30\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:51:37');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (57,50,11,'{\"post\":{\"id\":50,\"academic_year_id\":1,\"title\":\"Ninoy Aquino Day\",\"slug\":\"ninoy-aquino-day\",\"excerpt\":\"Sa paggunita natin sa Ninoy Aquino Day, ating binabalikan ang isang mahalagang bahagi ng kasaysayan ng Pilipinas ang tapang ng isang Pilipinong piniling ipaglaban ang kalayaan at demokrasya sa kabila ng panganib.\",\"content\":\"Sa paggunita natin sa Ninoy Aquino Day, ating binabalikan ang isang mahalagang bahagi ng kasaysayan ng Pilipinas ang tapang ng isang Pilipinong piniling ipaglaban ang kalayaan at demokrasya sa kabila ng panganib.\\r\\n\\r\\nAng buhay at sakripisyo ni Ninoy Aquino ay naging simbolo ng paninindigan para sa bayan. Ang kanyang pagkamatay ay hindi nagtapos sa kanyang laban; sa halip, nagmulat ito sa maraming Pilipino at nagbigay-lakas sa sambayanang manindigan para sa pagbabago, katarungan, at kalayaan.\\r\\n\\r\\nHigit sa pag-alala sa isang tao, ang araw na ito ay paalala sa kapangyarihan ng pagkakaisa. Ipinakita ng kasaysayan na kapag nagkaisa ang mga Pilipino at hindi natatakot ipahayag ang kanilang tinig, may kakayahan tayong harapin ang anumang hamon at ipaglaban ang nararapat.\\r\\n\\r\\nNawa’y magsilbing inspirasyon ang kanyang sakripisyo sa bawat Pilipino upang maging mapanindigan, makialam sa mga usaping panlipunan, at gamitin ang ating kalayaan nang may pananagutan.\\r\\n\\r\\nSa araw na ito, ating alalahanin si Ninoy Aquino hindi lamang bilang isang bayani ng nakaraan, kundi bilang paalala na ang tunay na pagmamahal sa bayan ay nakikita sa tapang na manindigan, sa malasakit sa kapwa, at sa patuloy na pag-asa para sa isang mas makatarungan at malayang Pilipinas.\\r\\n\\r\\nkatha ni P. E. Baustista\\r\\n\\r\\n#DMMMSUNLUC\\r\\n#nluccsbo\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-21 13:22:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:15:26\",\"updated_at\":\"2026-09-01 13:51:37\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":18,\"post_id\":50,\"file_path\":\"uploads/posts/post_50_0979174204dbcb89.jpg\",\"original_name\":\"781053443_1501952355282785_7552588831754086645_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:51:37\"}]}','Saved publication',1,'2026-09-01 13:51:37');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (58,49,2,'{\"post\":{\"id\":49,\"academic_year_id\":1,\"title\":\"👀 YOOHOO, DITO ANG TINGIN!📢\",\"slug\":\"yoohoo-dito-ang-tingin\",\"excerpt\":\"Isang mahalagang paalala para sa ating mga Iskolar ng Bayan ng DMMMSU-North La Union Campus.\\r\\nAng ating Midterm Examination para sa unang semestre ay gaganapin sa:\\r\\n\\r\\n🗓️ August 25, 26, at 27, 2026\\r\\n\\r\\nPaki-adjust na ang mga schedules at mag-ready na para sa mga reviewers. Huwag kalimutan magpahinga at kumain nang maayos!\\r\\n\\r\\nGod bless, everyone! Padayon! 💚\\r\\n\\r\\nkatha ni J.E. TRIDANIO\\r\\n\\r\\n#DMMMSUNLUC\\r\\n#nluccsbo\\r\\n#Midterms2026\",\"content\":\"\",\"category\":\"nluc\",\"label\":\"NLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-17 20:55:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:14:18\",\"updated_at\":\"2026-08-24 16:14:18\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:51:54');
