INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (60,48,2,'{\"post\":{\"id\":48,\"academic_year_id\":1,\"title\":\"Pens up! Papers out! 📝\",\"slug\":\"pens-up-papers-out\",\"excerpt\":\"To all DMMMSU-NLUC students taking the Midterm Examinations — you’ve studied hard, you’ve prepared, and now it’s your time to shine! 💪\\r\\n\\r\\nFrom the DMMMSU-NLUC Campus Student Body Organization, we’re sending you all the good vibes and encouragement as you take your Midterm Examinations.\\r\\nGood luck! Do your best and trust the process.\\r\\n\\r\\nGOOD LUCK, NLUcians! We’re rooting for you! 💚\\r\\n\\r\\n#DMMMSUNLUC\\r\\n#CSBO\\r\\n#Midterms2026\",\"content\":\"\",\"category\":\"nluc\",\"label\":\"NLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-16 20:43:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:13:21\",\"updated_at\":\"2026-08-24 16:13:21\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:52:13');
