INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (62,44,6,'{\"post\":{\"id\":44,\"academic_year_id\":1,\"title\":\"📢 𝐀𝐍𝐍𝐎𝐔𝐍𝐂𝐄𝐌𝐄𝐍𝐓 | 𝐑𝐄𝐒𝐂𝐇𝐄𝐃𝐔𝐋𝐈𝐍𝐆 𝐎𝐅 𝐌𝐈𝐃𝐓𝐄𝐑𝐌 𝐄𝐗𝐀𝐌𝐈𝐍𝐀𝐓𝐈𝐎𝐍𝐒\",\"slug\":\"publication-6\",\"excerpt\":\"Due to the disruption of classes brought about by the prevailing weather conditions, the schedule of the 𝐌𝐢𝐝𝐭𝐞𝐫𝐦 𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧𝐬 has been 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 to provide students and faculty with sufficient time to prepare and to ensure that academic activities can proceed in an orderly manner.\",\"content\":\"Due to the disruption of classes brought about by the prevailing weather conditions, the schedule of the 𝐌𝐢𝐝𝐭𝐞𝐫𝐦 𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧𝐬 has been 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 to provide students and faculty with sufficient time to prepare and to ensure that academic activities can proceed in an orderly manner.\\r\\nAs per the 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 𝐞𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧 𝐝𝐚𝐭𝐞𝐬 𝐬𝐮𝐛𝐦𝐢𝐭𝐭𝐞𝐝 𝐛𝐲 𝐭𝐡𝐞 𝐎𝐟𝐟𝐢𝐜𝐞 𝐨𝐟 𝐭𝐡𝐞 𝐕𝐢𝐜𝐞 𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭 𝐟𝐨𝐫 𝐀𝐜𝐚𝐝𝐞𝐦𝐢𝐜 𝐀𝐟𝐟𝐚𝐢𝐫𝐬 (𝐎𝐕𝐏𝐀𝐀), the Midterm Examinations will now be conducted on 𝐀𝐮𝐠𝐮𝐬𝐭 18–20, 2026.\\r\\nWith this adjustment, everyone is advised to disregard the previously issued memorandum regarding the Midterm Examination schedule, as the dates indicated therein have been superseded by the newly rectified schedule.\\r\\nWe encourage everyone to take note of the new dates and make the necessary adjustments to your study plans, schedules, and other preparations. Kindly stay updated for any succeeding announcements regarding the detailed examination schedule and other relevant instructions.\",\"category\":\"sluc\",\"label\":\"SLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-07 21:12:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":6,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:05:35\",\"updated_at\":\"2026-09-01 13:11:56\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:52:42');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (63,44,7,'{\"post\":{\"id\":44,\"academic_year_id\":1,\"title\":\"📢 𝐀𝐍𝐍𝐎𝐔𝐍𝐂𝐄𝐌𝐄𝐍𝐓 | 𝐑𝐄𝐒𝐂𝐇𝐄𝐃𝐔𝐋𝐈𝐍𝐆 𝐎𝐅 𝐌𝐈𝐃𝐓𝐄𝐑𝐌 𝐄𝐗𝐀𝐌𝐈𝐍𝐀𝐓𝐈𝐎𝐍𝐒\",\"slug\":\"publication-6\",\"excerpt\":\"Due to the disruption of classes brought about by the prevailing weather conditions, the schedule of the 𝐌𝐢𝐝𝐭𝐞𝐫𝐦 𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧𝐬 has been 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 to provide students and faculty with sufficient time to prepare and to ensure that academic activities can proceed in an orderly manner.\",\"content\":\"Due to the disruption of classes brought about by the prevailing weather conditions, the schedule of the 𝐌𝐢𝐝𝐭𝐞𝐫𝐦 𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧𝐬 has been 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 to provide students and faculty with sufficient time to prepare and to ensure that academic activities can proceed in an orderly manner.\\r\\nAs per the 𝐫𝐞𝐬𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝 𝐞𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧 𝐝𝐚𝐭𝐞𝐬 𝐬𝐮𝐛𝐦𝐢𝐭𝐭𝐞𝐝 𝐛𝐲 𝐭𝐡𝐞 𝐎𝐟𝐟𝐢𝐜𝐞 𝐨𝐟 𝐭𝐡𝐞 𝐕𝐢𝐜𝐞 𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭 𝐟𝐨𝐫 𝐀𝐜𝐚𝐝𝐞𝐦𝐢𝐜 𝐀𝐟𝐟𝐚𝐢𝐫𝐬 (𝐎𝐕𝐏𝐀𝐀), the Midterm Examinations will now be conducted on 𝐀𝐮𝐠𝐮𝐬𝐭 18–20, 2026.\\r\\nWith this adjustment, everyone is advised to disregard the previously issued memorandum regarding the Midterm Examination schedule, as the dates indicated therein have been superseded by the newly rectified schedule.\\r\\nWe encourage everyone to take note of the new dates and make the necessary adjustments to your study plans, schedules, and other preparations. Kindly stay updated for any succeeding announcements regarding the detailed examination schedule and other relevant instructions.\",\"category\":\"sluc\",\"label\":\"SLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-07 21:12:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:05:35\",\"updated_at\":\"2026-09-01 13:52:42\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":21,\"post_id\":44,\"file_path\":\"uploads/posts/post_44_e7a54e41650d6d65.jpg\",\"original_name\":\"767430925_1354384186904620_936484165768812276_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:52:42\"}]}','Saved publication',1,'2026-09-01 13:52:42');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (64,42,6,'{\"post\":{\"id\":42,\"academic_year_id\":1,\"title\":\"𝐀𝐃𝐕𝐈𝐒𝐎𝐑𝐘 | 𝐖𝐀𝐋𝐀𝐍𝐆 𝐏𝐀𝐒𝐎𝐊\",\"slug\":\"publication-4\",\"excerpt\":\"Pursuant to the Executive Order No. 43 and in view of the prevailing weather conditions, PGLU hereby announces the suspension of classes in all DMMMSU campuses on August 6, 2026.\\r\\n\\r\\nThe suspension covers all academic activities for the said date.\",\"content\":\"Pursuant to the Executive Order No. 43 and in view of the prevailing weather conditions, PGLU hereby announces the suspension of classes in all DMMMSU campuses on August 6, 2026.\\r\\n\\r\\nThe suspension covers all academic activities for the said date.\\r\\n\\r\\nStudents, faculty members, and personnel are advised to prioritize their safety and await further announcements through official university channels.\\r\\n\\r\\nPlease be guided accordingly.\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":1,\"is_university_featured\":1,\"status\":\"published\",\"published_at\":\"2026-08-05 19:37:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 15:58:57\",\"updated_at\":\"2026-09-01 13:10:22\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:53:01');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (65,42,7,'{\"post\":{\"id\":42,\"academic_year_id\":1,\"title\":\"𝐀𝐃𝐕𝐈𝐒𝐎𝐑𝐘 | 𝐖𝐀𝐋𝐀𝐍𝐆 𝐏𝐀𝐒𝐎𝐊\",\"slug\":\"publication-4\",\"excerpt\":\"Pursuant to the Executive Order No. 43 and in view of the prevailing weather conditions, PGLU hereby announces the suspension of classes in all DMMMSU campuses on August 6, 2026.\\r\\n\\r\\nThe suspension covers all academic activities for the said date.\",\"content\":\"Pursuant to the Executive Order No. 43 and in view of the prevailing weather conditions, PGLU hereby announces the suspension of classes in all DMMMSU campuses on August 6, 2026.\\r\\n\\r\\nThe suspension covers all academic activities for the said date.\\r\\n\\r\\nStudents, faculty members, and personnel are advised to prioritize their safety and await further announcements through official university channels.\\r\\n\\r\\nPlease be guided accordingly.\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":1,\"is_university_featured\":1,\"status\":\"published\",\"published_at\":\"2026-08-05 19:37:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 15:58:57\",\"updated_at\":\"2026-09-01 13:10:22\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":22,\"post_id\":42,\"file_path\":\"uploads/posts/post_42_a70dd18c36026634.jpg\",\"original_name\":\"764845230_1528522139287585_374589350318008315_n (1).jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:53:01\"}]}','Saved publication',1,'2026-09-01 13:53:01');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (66,43,10,'{\"post\":{\"id\":43,\"academic_year_id\":1,\"title\":\"𝗕𝗘 𝗪𝗘𝗔𝗧𝗛𝗘𝗥-𝗥𝗘𝗔𝗗𝗬 | 𝗠𝗮𝗴𝗶𝗻𝗴 𝗵𝗮𝗻𝗱𝗮, 𝗠𝗮𝗮𝗹𝗮𝗺, 𝗮𝘁 𝗟𝗶𝗴𝘁𝗮𝘀\",\"slug\":\"publication-5\",\"excerpt\":\"𝐁𝐞 𝐖𝐞𝐚𝐭𝐡𝐞𝐫-𝐫𝐞𝐚𝐝𝐲\\r\\n— Sa nagbabadyang lagay ng panahon, mahalaga ang maging handa at maingat sa mga banta nang anumang sakuna at maprotektahan ang ating sarili.\",\"content\":\"𝐁𝐞 𝐖𝐞𝐚𝐭𝐡𝐞𝐫-𝐫𝐞𝐚𝐝𝐲\\r\\n— Sa nagbabadyang lagay ng panahon, mahalaga ang maging handa at maingat sa mga banta nang anumang sakuna at maprotektahan ang ating sarili.\\r\\n𝐒𝐭𝐚𝐲 𝐚𝐥𝐞𝐫𝐭\\r\\n— Bigyang atensyon ang paligid sa mga malalakas na pag-ulan, pagbaha, pagtaas ng tubig, at iba pang panganib na dulot ng masamang panahon. Alamin ang color coded rainfall advisories ng PAGASA.\\r\\n𝐒𝐭𝐚𝐲 𝐢𝐧𝐟𝐨𝐫𝐦𝐞𝐝\\r\\n— Manatiling maalam at manatiling nakaabang sa mga opisyal na mga anunsyo mula sa mga mapagkakatiwalaang account o pages. Alamin ang mga Emergency Hotlines.\\r\\n𝐊𝐞𝐞𝐩 𝐬𝐚𝐟𝐞 𝐚𝐧𝐝 𝐝𝐫𝐲\\r\\n— Manatili sa loob ng tahanan. Unahin ang inyong kaligtasan.  Manatili sa ligtas na lugar hangga\'t maaari. Ingatan ang inyong sarili at ang isa\'t isa, mga SLUCians.\\r\\nSa bawat unos na ating kinakaharap, nawa\'y manaig ang kahandaan kaysa pangamba, ang tamang impormasyon kaysa haka-haka, at ang pag-iingat kaysa pakikipagsasapalaran. Bilang mga SLUCians, sama-sama nating unahin ang kaligtasan at maging bahagi ng isang handa, matatag, at responsableng komunidad.\",\"category\":\"sluc\",\"label\":\"SLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-03 22:33:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":6,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:03:50\",\"updated_at\":\"2026-08-24 16:22:40\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:55:45');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (67,43,11,'{\"post\":{\"id\":43,\"academic_year_id\":1,\"title\":\"𝗕𝗘 𝗪𝗘𝗔𝗧𝗛𝗘𝗥-𝗥𝗘𝗔𝗗𝗬 | 𝗠𝗮𝗴𝗶𝗻𝗴 𝗵𝗮𝗻𝗱𝗮, 𝗠𝗮𝗮𝗹𝗮𝗺, 𝗮𝘁 𝗟𝗶𝗴𝘁𝗮𝘀\",\"slug\":\"publication-5\",\"excerpt\":\"𝐁𝐞 𝐖𝐞𝐚𝐭𝐡𝐞𝐫-𝐫𝐞𝐚𝐝𝐲\\r\\n— Sa nagbabadyang lagay ng panahon, mahalaga ang maging handa at maingat sa mga banta nang anumang sakuna at maprotektahan ang ating sarili.\",\"content\":\"𝐁𝐞 𝐖𝐞𝐚𝐭𝐡𝐞𝐫-𝐫𝐞𝐚𝐝𝐲\\r\\n— Sa nagbabadyang lagay ng panahon, mahalaga ang maging handa at maingat sa mga banta nang anumang sakuna at maprotektahan ang ating sarili.\\r\\n𝐒𝐭𝐚𝐲 𝐚𝐥𝐞𝐫𝐭\\r\\n— Bigyang atensyon ang paligid sa mga malalakas na pag-ulan, pagbaha, pagtaas ng tubig, at iba pang panganib na dulot ng masamang panahon. Alamin ang color coded rainfall advisories ng PAGASA.\\r\\n𝐒𝐭𝐚𝐲 𝐢𝐧𝐟𝐨𝐫𝐦𝐞𝐝\\r\\n— Manatiling maalam at manatiling nakaabang sa mga opisyal na mga anunsyo mula sa mga mapagkakatiwalaang account o pages. Alamin ang mga Emergency Hotlines.\\r\\n𝐊𝐞𝐞𝐩 𝐬𝐚𝐟𝐞 𝐚𝐧𝐝 𝐝𝐫𝐲\\r\\n— Manatili sa loob ng tahanan. Unahin ang inyong kaligtasan.  Manatili sa ligtas na lugar hangga\'t maaari. Ingatan ang inyong sarili at ang isa\'t isa, mga SLUCians.\\r\\nSa bawat unos na ating kinakaharap, nawa\'y manaig ang kahandaan kaysa pangamba, ang tamang impormasyon kaysa haka-haka, at ang pag-iingat kaysa pakikipagsasapalaran. Bilang mga SLUCians, sama-sama nating unahin ang kaligtasan at maging bahagi ng isang handa, matatag, at responsableng komunidad.\",\"category\":\"sluc\",\"label\":\"SLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-03 22:33:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:03:50\",\"updated_at\":\"2026-09-01 13:55:45\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":23,\"post_id\":43,\"file_path\":\"uploads/posts/post_43_9796c3e96c940113.jpg\",\"original_name\":\"11.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:55:45\"},{\"id\":24,\"post_id\":43,\"file_path\":\"uploads/posts/post_43_7e4b83b13df58c73.jpg\",\"original_name\":\"12.jpg\",\"media_id\":null,\"sort_order\":1,\"created_at\":\"2026-09-01 13:55:45\"},{\"id\":25,\"post_id\":43,\"file_path\":\"uploads/posts/post_43_2a9dcfb93524ac52.jpg\",\"original_name\":\"13.jpg\",\"media_id\":null,\"sort_order\":2,\"created_at\":\"2026-09-01 13:55:45\"}]}','Saved publication',1,'2026-09-01 13:55:45');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (68,41,2,'{\"post\":{\"id\":41,\"academic_year_id\":1,\"title\":\"𝐀𝐃𝐕𝐈𝐒𝐎𝐑𝐘\",\"slug\":\"publication-3\",\"excerpt\":\"Please be informed that face-to-face classes in all DMMMSU campuses are suspended on August 4, 2026. Alternative learning arrangements shall be implemented as prescribed by the respective instructors.\\r\\nFor complete details, please refer to the official advisory.\\r\\nhttps://m.facebook.com/story.php?story_fbid=1574056418066428&id=100063862548392 \\r\\nStay safe, everyone. See less\",\"content\":\"\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-03 20:21:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 15:55:51\",\"updated_at\":\"2026-09-01 13:10:04\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:56:30');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (69,41,3,'{\"post\":{\"id\":41,\"academic_year_id\":1,\"title\":\"𝐀𝐃𝐕𝐈𝐒𝐎𝐑𝐘\",\"slug\":\"publication-3\",\"excerpt\":\"Please be informed that face-to-face classes in all DMMMSU campuses are suspended on August 4, 2026. Alternative learning arrangements shall be implemented as prescribed by the respective instructors.\\r\\nFor complete details, please refer to the official advisory.\\r\\nhttps://m.facebook.com/story.php?story_fbid=1574056418066428&id=100063862548392 \\r\\nStay safe, everyone. See less\",\"content\":\"\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-03 20:21:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 15:55:51\",\"updated_at\":\"2026-09-01 13:10:04\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":26,\"post_id\":41,\"file_path\":\"uploads/posts/post_41_074103d2d5cc29fe.jpg\",\"original_name\":\"1.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:56:30\"},{\"id\":27,\"post_id\":41,\"file_path\":\"uploads/posts/post_41_9e83f281e6ed6d01.jpg\",\"original_name\":\"2.jpg\",\"media_id\":null,\"sort_order\":1,\"created_at\":\"2026-09-01 13:56:30\"}]}','Saved publication',1,'2026-09-01 13:56:30');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (70,11,5,'{\"post\":{\"id\":11,\"academic_year_id\":1,\"title\":\"𝐎𝐅𝐅𝐈𝐂𝐈𝐀𝐋 𝐒𝐓𝐀𝐓𝐄𝐌𝐄𝐍𝐓 𝐎𝐅 𝐓𝐇𝐄 𝐔𝐍𝐈𝐕𝐄𝐑𝐒𝐈𝐓𝐘 𝐒𝐓𝐔𝐃𝐄𝐍𝐓 𝐂𝐎𝐔𝐍𝐂𝐈𝐋\",\"slug\":\"publication-2\",\"excerpt\":\"The University Student Council (USC) acknowledges the concerns raised by students regarding the current weather conditions and the possibility of class suspension due to heavy rainfall.\",\"content\":\"Isang Mapagpalayang Araw.\\r\\n\\r\\nThe University Student Council (USC) acknowledges the concerns raised by students regarding the current weather conditions and the possibility of class suspension due to heavy rainfall.\\r\\n\\r\\nPlease be informed that the USC has been actively coordinating and communicating with the University Administration regarding these concerns. We recognize the importance of ensuring the safety and welfare of all students, faculty members, and personnel, especially during adverse weather conditions.\\r\\n\\r\\nHowever, we would also like to clarify that the declaration of class suspensions is governed by existing university policies, guidelines, and protocols. Such decisions undergo proper assessment and due process and cannot be implemented solely upon request or preference. While the USC serves as the voice of the student body and continuously relays student concerns to the appropriate offices, the authority to declare suspensions remains subject to established institutional procedures.\\r\\n\\r\\nFurthermore, we would like to clarify that the anonymous post currently circulating regarding this matter did not originate from the University Student Council. As a student government, we uphold the principles of transparency, accountability, and responsible communication. We release official statements through our authorized platforms and ensure that all information disseminated by the USC bears proper accountability and representation.\\r\\n\\r\\nIn the meantime, the USC strongly encourages students to prioritize their safety. If you believe that traveling to campus poses a risk to your well-being due to weather conditions or other related circumstances, please exercise your judgment accordingly. We advise affected students to communicate with their respective instructors and respectfully seek consideration regarding their situation.\\r\\n\\r\\nThe USC remains committed to monitoring developments, relaying student concerns to the administration, and advocating for the welfare of the student body. We ask everyone to remain vigilant, stay informed through official university channels, and prioritize safety at all times.\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-03 11:04:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-15 19:23:42\",\"updated_at\":\"2026-09-01 13:10:04\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:56:48');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (71,11,6,'{\"post\":{\"id\":11,\"academic_year_id\":1,\"title\":\"𝐎𝐅𝐅𝐈𝐂𝐈𝐀𝐋 𝐒𝐓𝐀𝐓𝐄𝐌𝐄𝐍𝐓 𝐎𝐅 𝐓𝐇𝐄 𝐔𝐍𝐈𝐕𝐄𝐑𝐒𝐈𝐓𝐘 𝐒𝐓𝐔𝐃𝐄𝐍𝐓 𝐂𝐎𝐔𝐍𝐂𝐈𝐋\",\"slug\":\"publication-2\",\"excerpt\":\"The University Student Council (USC) acknowledges the concerns raised by students regarding the current weather conditions and the possibility of class suspension due to heavy rainfall.\",\"content\":\"Isang Mapagpalayang Araw.\\r\\n\\r\\nThe University Student Council (USC) acknowledges the concerns raised by students regarding the current weather conditions and the possibility of class suspension due to heavy rainfall.\\r\\n\\r\\nPlease be informed that the USC has been actively coordinating and communicating with the University Administration regarding these concerns. We recognize the importance of ensuring the safety and welfare of all students, faculty members, and personnel, especially during adverse weather conditions.\\r\\n\\r\\nHowever, we would also like to clarify that the declaration of class suspensions is governed by existing university policies, guidelines, and protocols. Such decisions undergo proper assessment and due process and cannot be implemented solely upon request or preference. While the USC serves as the voice of the student body and continuously relays student concerns to the appropriate offices, the authority to declare suspensions remains subject to established institutional procedures.\\r\\n\\r\\nFurthermore, we would like to clarify that the anonymous post currently circulating regarding this matter did not originate from the University Student Council. As a student government, we uphold the principles of transparency, accountability, and responsible communication. We release official statements through our authorized platforms and ensure that all information disseminated by the USC bears proper accountability and representation.\\r\\n\\r\\nIn the meantime, the USC strongly encourages students to prioritize their safety. If you believe that traveling to campus poses a risk to your well-being due to weather conditions or other related circumstances, please exercise your judgment accordingly. We advise affected students to communicate with their respective instructors and respectfully seek consideration regarding their situation.\\r\\n\\r\\nThe USC remains committed to monitoring developments, relaying student concerns to the administration, and advocating for the welfare of the student body. We ask everyone to remain vigilant, stay informed through official university channels, and prioritize safety at all times.\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-03 11:04:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-15 19:23:42\",\"updated_at\":\"2026-09-01 13:10:04\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":28,\"post_id\":11,\"file_path\":\"uploads/posts/post_11_f611253170d588bd.jpg\",\"original_name\":\"761747527_1526379522835180_6287043047617718657_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:56:48\"}]}','Saved publication',1,'2026-09-01 13:56:48');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (72,10,7,'{\"post\":{\"id\":10,\"academic_year_id\":1,\"title\":\"𝐑𝐨𝐜𝐚𝐛𝐞𝐫𝐭𝐞 𝐒𝐮𝐜𝐜𝐞𝐞𝐝𝐬 𝐚𝐬 𝐂𝐒𝐁𝐎 𝐂𝐡𝐚𝐢𝐫𝐩𝐞𝐫𝐬𝐨𝐧; 𝐌𝐞𝐧𝐝𝐨𝐳𝐚 𝐄𝐥𝐞𝐜𝐭𝐞𝐝 𝐚𝐬 𝐍𝐞𝐰 𝐕𝐢𝐜𝐞 𝐂𝐡𝐚𝐢𝐫\",\"slug\":\"publication\",\"excerpt\":\"Subsequent to the election of former Chairperson Michael Dean M. Malonzo to the University Student Council (USC), and pursuant to CSBO Resolution No. 2, Series of 2026–2027, former Vice Chairperson Edrian D. Rocaberte assumed the office of Chairperson of the CSBO. Due to the said succession, the Office of the Vice Chairperson became vacant.\",\"content\":\"Subsequent to the election of former Chairperson Michael Dean M. Malonzo to the University Student Council (USC), and pursuant to CSBO Resolution No. 2, Series of 2026–2027, former Vice Chairperson Edrian D. Rocaberte assumed the office of Chairperson of the CSBO. Due to the said succession, the Office of the Vice Chairperson became vacant.\\r\\n\\r\\nConsequently, in accordance with the Student Handbook, Article XI - Vacancies and Succession, Section 2, a Special Election was held on July 15, 2026, during which Hermes Aldrich J. Mendoza was elected as the new Vice Chairperson to fill the said vacancy.\\r\\n\\r\\nThrough the implementation of succession process and conduct of Special Election, the CSBO is further reiterating its stand on having a consistent and stable leadership that will provide quality service to the SLUC studentry for the academic year 2026-2027.\\r\\n\\r\\n#CSBOxCSC\\r\\n#TatakSLUCian\",\"category\":\"sluc\",\"label\":\"SLUC\",\"image\":null,\"is_featured\":1,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-07-22 17:16:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-15 19:16:57\",\"updated_at\":\"2026-08-24 16:00:43\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:57:07');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (73,10,8,'{\"post\":{\"id\":10,\"academic_year_id\":1,\"title\":\"𝐑𝐨𝐜𝐚𝐛𝐞𝐫𝐭𝐞 𝐒𝐮𝐜𝐜𝐞𝐞𝐝𝐬 𝐚𝐬 𝐂𝐒𝐁𝐎 𝐂𝐡𝐚𝐢𝐫𝐩𝐞𝐫𝐬𝐨𝐧; 𝐌𝐞𝐧𝐝𝐨𝐳𝐚 𝐄𝐥𝐞𝐜𝐭𝐞𝐝 𝐚𝐬 𝐍𝐞𝐰 𝐕𝐢𝐜𝐞 𝐂𝐡𝐚𝐢𝐫\",\"slug\":\"publication\",\"excerpt\":\"Subsequent to the election of former Chairperson Michael Dean M. Malonzo to the University Student Council (USC), and pursuant to CSBO Resolution No. 2, Series of 2026–2027, former Vice Chairperson Edrian D. Rocaberte assumed the office of Chairperson of the CSBO. Due to the said succession, the Office of the Vice Chairperson became vacant.\",\"content\":\"Subsequent to the election of former Chairperson Michael Dean M. Malonzo to the University Student Council (USC), and pursuant to CSBO Resolution No. 2, Series of 2026–2027, former Vice Chairperson Edrian D. Rocaberte assumed the office of Chairperson of the CSBO. Due to the said succession, the Office of the Vice Chairperson became vacant.\\r\\n\\r\\nConsequently, in accordance with the Student Handbook, Article XI - Vacancies and Succession, Section 2, a Special Election was held on July 15, 2026, during which Hermes Aldrich J. Mendoza was elected as the new Vice Chairperson to fill the said vacancy.\\r\\n\\r\\nThrough the implementation of succession process and conduct of Special Election, the CSBO is further reiterating its stand on having a consistent and stable leadership that will provide quality service to the SLUC studentry for the academic year 2026-2027.\\r\\n\\r\\n#CSBOxCSC\\r\\n#TatakSLUCian\",\"category\":\"sluc\",\"label\":\"SLUC\",\"image\":null,\"is_featured\":1,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-07-22 17:16:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-15 19:16:57\",\"updated_at\":\"2026-08-24 16:00:43\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":29,\"post_id\":10,\"file_path\":\"uploads/posts/post_10_c75f846e333b7885.jpg\",\"original_name\":\"749300662_993920943483283_6310725844511423514_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:57:07\"}]}','Saved publication',1,'2026-09-01 13:57:07');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (74,47,2,'{\"post\":{\"id\":47,\"academic_year_id\":1,\"title\":\"#MLUCCSBOupdates | 𝐉𝐀𝐂𝐀𝐁𝐀𝐍 𝐀𝐒𝐒𝐔𝐌𝐄𝐒 𝐑𝐎𝐋𝐄 𝐀𝐒 𝐓𝐇𝐄 𝐍𝐄𝐖 𝐂𝐒𝐁𝐎 𝐒𝐄𝐂𝐑𝐄𝐓𝐀𝐑𝐘 𝐅𝐎𝐑 𝐀𝐘 𝟐𝟎𝟐𝟔-𝟐𝟎𝟐𝟕\",\"slug\":\"mluccsboupdates-3\",\"excerpt\":\"As per Resolution No. 2, Series of 2026-2027, 𝐑𝐚𝐲 𝐉𝐚𝐬𝐩𝐞𝐫 𝐏. 𝐉𝐚𝐜𝐚𝐛𝐚𝐧 of the College of Arts and Sciences is officially the new Secretary of the Campus Student Body Organization (CSBO) for Academic Year 2026-2027.\",\"content\":\"As per Resolution No. 2, Series of 2026-2027, 𝐑𝐚𝐲 𝐉𝐚𝐬𝐩𝐞𝐫 𝐏. 𝐉𝐚𝐜𝐚𝐛𝐚𝐧 of the College of Arts and Sciences is officially the new Secretary of the Campus Student Body Organization (CSBO) for Academic Year 2026-2027.\\r\\n\\r\\n​Following the election of the former Secretary, Joe Lei Yane P. Sotelo, to the University Student Council, this vacancy has been filled to ensure the continuous and effective functioning of the organization.\\r\\n\\r\\n​With this, the CSBO reaffirms its commitment to strengthening student leadership, promoting participatory governance, and actively advancing the welfare of the entire DMMMSU-MLUC studentry.\\r\\n\\r\\n𝑪𝒐𝒏𝒈𝒓𝒂𝒕𝒖𝒍𝒂𝒕𝒊𝒐𝒏𝒔 𝒐𝒏 𝒕𝒉𝒊𝒔 𝒅𝒆𝒔𝒊𝒈𝒏𝒂𝒕𝒊𝒐𝒏, 𝑹𝒂𝒚 𝑱𝒂𝒔𝒑𝒆𝒓! 𝑴𝒂𝒚 𝒕𝒉𝒊𝒔 𝒕𝒆𝒓𝒎 𝒃𝒆 𝒎𝒂𝒓𝒌𝒆𝒅 𝒃𝒚 𝒅𝒆𝒅𝒊𝒄𝒂𝒕𝒆𝒅 𝒔𝒆𝒓𝒗𝒊𝒄𝒆, 𝒆𝒙𝒄𝒆𝒍𝒍𝒆𝒏𝒄𝒆, 𝒂𝒏𝒅 𝒊𝒏𝒕𝒆𝒈𝒓𝒊𝒕𝒚.\\r\\n\\r\\n**\\r\\nWords | S. Villacorta\\r\\n\\r\\n#MLUC_CSBOxCSC’26\\r\\n#DMMMSU_MLUC\",\"category\":\"mluc\",\"label\":\"MLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-07-19 16:09:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:10:22\",\"updated_at\":\"2026-08-24 16:10:22\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:57:21');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (75,47,3,'{\"post\":{\"id\":47,\"academic_year_id\":1,\"title\":\"#MLUCCSBOupdates | 𝐉𝐀𝐂𝐀𝐁𝐀𝐍 𝐀𝐒𝐒𝐔𝐌𝐄𝐒 𝐑𝐎𝐋𝐄 𝐀𝐒 𝐓𝐇𝐄 𝐍𝐄𝐖 𝐂𝐒𝐁𝐎 𝐒𝐄𝐂𝐑𝐄𝐓𝐀𝐑𝐘 𝐅𝐎𝐑 𝐀𝐘 𝟐𝟎𝟐𝟔-𝟐𝟎𝟐𝟕\",\"slug\":\"mluccsboupdates-3\",\"excerpt\":\"As per Resolution No. 2, Series of 2026-2027, 𝐑𝐚𝐲 𝐉𝐚𝐬𝐩𝐞𝐫 𝐏. 𝐉𝐚𝐜𝐚𝐛𝐚𝐧 of the College of Arts and Sciences is officially the new Secretary of the Campus Student Body Organization (CSBO) for Academic Year 2026-2027.\",\"content\":\"As per Resolution No. 2, Series of 2026-2027, 𝐑𝐚𝐲 𝐉𝐚𝐬𝐩𝐞𝐫 𝐏. 𝐉𝐚𝐜𝐚𝐛𝐚𝐧 of the College of Arts and Sciences is officially the new Secretary of the Campus Student Body Organization (CSBO) for Academic Year 2026-2027.\\r\\n\\r\\n​Following the election of the former Secretary, Joe Lei Yane P. Sotelo, to the University Student Council, this vacancy has been filled to ensure the continuous and effective functioning of the organization.\\r\\n\\r\\n​With this, the CSBO reaffirms its commitment to strengthening student leadership, promoting participatory governance, and actively advancing the welfare of the entire DMMMSU-MLUC studentry.\\r\\n\\r\\n𝑪𝒐𝒏𝒈𝒓𝒂𝒕𝒖𝒍𝒂𝒕𝒊𝒐𝒏𝒔 𝒐𝒏 𝒕𝒉𝒊𝒔 𝒅𝒆𝒔𝒊𝒈𝒏𝒂𝒕𝒊𝒐𝒏, 𝑹𝒂𝒚 𝑱𝒂𝒔𝒑𝒆𝒓! 𝑴𝒂𝒚 𝒕𝒉𝒊𝒔 𝒕𝒆𝒓𝒎 𝒃𝒆 𝒎𝒂𝒓𝒌𝒆𝒅 𝒃𝒚 𝒅𝒆𝒅𝒊𝒄𝒂𝒕𝒆𝒅 𝒔𝒆𝒓𝒗𝒊𝒄𝒆, 𝒆𝒙𝒄𝒆𝒍𝒍𝒆𝒏𝒄𝒆, 𝒂𝒏𝒅 𝒊𝒏𝒕𝒆𝒈𝒓𝒊𝒕𝒚.\\r\\n\\r\\n**\\r\\nWords | S. Villacorta\\r\\n\\r\\n#MLUC_CSBOxCSC’26\\r\\n#DMMMSU_MLUC\",\"category\":\"mluc\",\"label\":\"MLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-07-19 16:09:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:10:22\",\"updated_at\":\"2026-08-24 16:10:22\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":30,\"post_id\":47,\"file_path\":\"uploads/posts/post_47_68b985928bbe1702.jpg\",\"original_name\":\"767400861_1647533637375711_2749044493193808341_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:57:21\"}]}','Saved publication',1,'2026-09-01 13:57:21');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (76,46,2,'{\"post\":{\"id\":46,\"academic_year_id\":1,\"title\":\"#MLUCCSBOupdates | 𝑴𝒂𝒍𝒖𝒈𝒐𝒅 𝒏𝒂 𝒑𝒂𝒈𝒃𝒂𝒕𝒊, 𝑬𝒕𝒉𝒊𝒄𝒂𝒍 𝑺𝒕𝒂𝒏𝒅𝒂𝒓𝒅𝒔 𝑶𝒇𝒇𝒊𝒄𝒆𝒓 𝑱𝒐𝒆 𝑳𝒆𝒊 𝒀𝒂𝒏𝒆 𝑷. 𝑺𝒐𝒕𝒆𝒍𝒐!\",\"slug\":\"mluccsboupdates-2\",\"excerpt\":\"The University Student Council successfully held its elections last July 8, 2026, at the DMMMSU North La Union Campus (NLUC), drawing active participation and attendance from the university\'s various campuses.\\r\\n​Following a competitive election cycle, the newly elected student leaders who will spearhead the council have been officially announced:\\r\\n\\r\\n• ​𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭: 𝐌𝐫. 𝐌𝐢𝐜𝐡𝐚𝐞𝐥 𝐃𝐞𝐚𝐧 𝐌𝐚𝐥𝐨𝐧𝐳𝐨\\r\\n• ​𝐕𝐢𝐜𝐞 𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭:𝐌𝐫. 𝐅𝐫𝐚𝐧𝐜𝐢𝐬 𝐏𝐚𝐮𝐥 𝐒𝐚𝐠𝐚𝐝\\r\\n• ​𝐄𝐭𝐡𝐢𝐜𝐚𝐥 𝐒𝐭𝐚𝐧𝐝𝐚𝐫𝐝𝐬 𝐎𝐟𝐟𝐢𝐜𝐞𝐫: 𝐌𝐫. 𝐉𝐨𝐞 𝐋𝐞𝐢 𝐘𝐚𝐧𝐞 𝐏. 𝐒𝐨𝐭𝐞𝐥𝐨\",\"content\":\"The University Student Council successfully held its elections last July 8, 2026, at the DMMMSU North La Union Campus (NLUC), drawing active participation and attendance from the university\'s various campuses.\\r\\n​Following a competitive election cycle, the newly elected student leaders who will spearhead the council have been officially announced:\\r\\n\\r\\n• ​𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭: 𝐌𝐫. 𝐌𝐢𝐜𝐡𝐚𝐞𝐥 𝐃𝐞𝐚𝐧 𝐌𝐚𝐥𝐨𝐧𝐳𝐨\\r\\n• ​𝐕𝐢𝐜𝐞 𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭:𝐌𝐫. 𝐅𝐫𝐚𝐧𝐜𝐢𝐬 𝐏𝐚𝐮𝐥 𝐒𝐚𝐠𝐚𝐝\\r\\n• ​𝐄𝐭𝐡𝐢𝐜𝐚𝐥 𝐒𝐭𝐚𝐧𝐝𝐚𝐫𝐝𝐬 𝐎𝐟𝐟𝐢𝐜𝐞𝐫: 𝐌𝐫. 𝐉𝐨𝐞 𝐋𝐞𝐢 𝐘𝐚𝐧𝐞 𝐏. 𝐒𝐨𝐭𝐞𝐥𝐨\\r\\n\\r\\n​During an exclusive interview, Mr. Sotelo shared his statement for his term, stating, \\\"Being elected into the highest organization was really a privilege. Being ready to take the position was not solely understanding the duties of the ESO. However, it is important to note that being an ESO is also better understanding your surroundings. Since I started my leadership journey, I’ve seen a lot of leaders with different leadership perspectives. Yet, most leaders I’ve encountered are holding the title for survival. I\'ve seen, I’ve encountered, and I’ve experienced what a leader can do. 𝗦𝗼 𝗯𝗲𝗶𝗻𝗴 𝗮𝗻 𝗘𝗦𝗢, 𝗶𝘁 𝗶𝘀 𝘁𝗼 𝗽𝗿𝗼𝗺𝗼𝘁𝗲 𝘁𝗵𝗲 𝗰𝗼𝗱𝗲 𝗼𝗳 𝗰𝗼𝗻𝗱𝘂𝗰𝘁 𝗼𝗳 𝘁𝗵𝗲 𝗹𝗲𝗮𝗱𝗲𝗿𝘀 𝗮𝗻𝗱 𝗺𝗮𝗶𝗻𝘁𝗮𝗶𝗻 𝗮 𝗰𝗮𝗺𝗽𝘂𝘀 𝘁𝗵𝗮𝘁 𝗶𝘀 𝗳𝗿𝗲𝗲 𝗳𝗿𝗼𝗺 𝘁𝗵𝗲 𝗮𝗯𝘂𝘀𝗲 𝗼𝗳 𝗽𝗼𝘄𝗲𝗿. I’ve understood, and I’m ready to take the position. And when the result came, I was happy, and yet, I was thinking that it is a bigger arena to be elected in the highest level and carrying a university-wide responsibility. It was an opportunity to be an officer of the USC. \\\"\\r\\n\\r\\n​Ikinagagalak naming naging bahagi ka ng 𝐔𝐧𝐢𝐯𝐞𝐫𝐬𝐢𝐭𝐲 𝐒𝐭𝐮𝐝𝐞𝐧𝐭 𝐂𝐨𝐮𝐧𝐜𝐢𝐥. Ito ay isang tunay na patunay sa pandaigdigang kagalingan at kahusayan na iyong ipinamalas—at patuloy pang ipapamalas—para sa buong pamayanan ng DMMMSU.\\r\\n\\r\\n​𝑴𝒖𝒍𝒂 𝒔𝒂 𝑫𝑴𝑴𝑴𝑺𝑼 𝑴𝒊𝒅 𝑳𝒂 𝑼𝒏𝒊𝒐𝒏 𝑪𝒂𝒎𝒑𝒖𝒔, 𝒊𝒔𝒂𝒏𝒈 𝒎𝒂𝒍𝒖𝒈𝒐𝒅 𝒂𝒕 𝒎𝒂𝒊𝒏𝒊𝒕 𝒏𝒂 𝒑𝒂𝒈𝒃𝒂𝒕𝒊 𝒔𝒂 𝒏𝒂𝒈-𝒊𝒊𝒔𝒂𝒏𝒈 𝑱𝒐𝒆-𝒔𝒉𝒖𝒂 𝒏𝒈 𝑪𝑺𝑩𝑶, 𝑴𝒓. 𝑱𝒐𝒆 𝑳𝒆𝒊 𝒀𝒂𝒏𝒆 𝑷. 𝑺𝒐𝒕𝒆𝒍𝒐!\\r\\n\\r\\n**\\r\\nWords | S. Villacorta\\r\\nLayout | A. Galinato\\r\\n\\r\\n#MLUC_CSBOxCSC’26\\r\\n#DMMMSU_MLUC See less\",\"category\":\"mluc\",\"label\":\"MLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-07-09 16:08:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:09:19\",\"updated_at\":\"2026-08-24 16:09:19\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:57:38');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (77,46,3,'{\"post\":{\"id\":46,\"academic_year_id\":1,\"title\":\"#MLUCCSBOupdates | 𝑴𝒂𝒍𝒖𝒈𝒐𝒅 𝒏𝒂 𝒑𝒂𝒈𝒃𝒂𝒕𝒊, 𝑬𝒕𝒉𝒊𝒄𝒂𝒍 𝑺𝒕𝒂𝒏𝒅𝒂𝒓𝒅𝒔 𝑶𝒇𝒇𝒊𝒄𝒆𝒓 𝑱𝒐𝒆 𝑳𝒆𝒊 𝒀𝒂𝒏𝒆 𝑷. 𝑺𝒐𝒕𝒆𝒍𝒐!\",\"slug\":\"mluccsboupdates-2\",\"excerpt\":\"The University Student Council successfully held its elections last July 8, 2026, at the DMMMSU North La Union Campus (NLUC), drawing active participation and attendance from the university\'s various campuses.\\r\\n​Following a competitive election cycle, the newly elected student leaders who will spearhead the council have been officially announced:\\r\\n\\r\\n• ​𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭: 𝐌𝐫. 𝐌𝐢𝐜𝐡𝐚𝐞𝐥 𝐃𝐞𝐚𝐧 𝐌𝐚𝐥𝐨𝐧𝐳𝐨\\r\\n• ​𝐕𝐢𝐜𝐞 𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭:𝐌𝐫. 𝐅𝐫𝐚𝐧𝐜𝐢𝐬 𝐏𝐚𝐮𝐥 𝐒𝐚𝐠𝐚𝐝\\r\\n• ​𝐄𝐭𝐡𝐢𝐜𝐚𝐥 𝐒𝐭𝐚𝐧𝐝𝐚𝐫𝐝𝐬 𝐎𝐟𝐟𝐢𝐜𝐞𝐫: 𝐌𝐫. 𝐉𝐨𝐞 𝐋𝐞𝐢 𝐘𝐚𝐧𝐞 𝐏. 𝐒𝐨𝐭𝐞𝐥𝐨\",\"content\":\"The University Student Council successfully held its elections last July 8, 2026, at the DMMMSU North La Union Campus (NLUC), drawing active participation and attendance from the university\'s various campuses.\\r\\n​Following a competitive election cycle, the newly elected student leaders who will spearhead the council have been officially announced:\\r\\n\\r\\n• ​𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭: 𝐌𝐫. 𝐌𝐢𝐜𝐡𝐚𝐞𝐥 𝐃𝐞𝐚𝐧 𝐌𝐚𝐥𝐨𝐧𝐳𝐨\\r\\n• ​𝐕𝐢𝐜𝐞 𝐏𝐫𝐞𝐬𝐢𝐝𝐞𝐧𝐭:𝐌𝐫. 𝐅𝐫𝐚𝐧𝐜𝐢𝐬 𝐏𝐚𝐮𝐥 𝐒𝐚𝐠𝐚𝐝\\r\\n• ​𝐄𝐭𝐡𝐢𝐜𝐚𝐥 𝐒𝐭𝐚𝐧𝐝𝐚𝐫𝐝𝐬 𝐎𝐟𝐟𝐢𝐜𝐞𝐫: 𝐌𝐫. 𝐉𝐨𝐞 𝐋𝐞𝐢 𝐘𝐚𝐧𝐞 𝐏. 𝐒𝐨𝐭𝐞𝐥𝐨\\r\\n\\r\\n​During an exclusive interview, Mr. Sotelo shared his statement for his term, stating, \\\"Being elected into the highest organization was really a privilege. Being ready to take the position was not solely understanding the duties of the ESO. However, it is important to note that being an ESO is also better understanding your surroundings. Since I started my leadership journey, I’ve seen a lot of leaders with different leadership perspectives. Yet, most leaders I’ve encountered are holding the title for survival. I\'ve seen, I’ve encountered, and I’ve experienced what a leader can do. 𝗦𝗼 𝗯𝗲𝗶𝗻𝗴 𝗮𝗻 𝗘𝗦𝗢, 𝗶𝘁 𝗶𝘀 𝘁𝗼 𝗽𝗿𝗼𝗺𝗼𝘁𝗲 𝘁𝗵𝗲 𝗰𝗼𝗱𝗲 𝗼𝗳 𝗰𝗼𝗻𝗱𝘂𝗰𝘁 𝗼𝗳 𝘁𝗵𝗲 𝗹𝗲𝗮𝗱𝗲𝗿𝘀 𝗮𝗻𝗱 𝗺𝗮𝗶𝗻𝘁𝗮𝗶𝗻 𝗮 𝗰𝗮𝗺𝗽𝘂𝘀 𝘁𝗵𝗮𝘁 𝗶𝘀 𝗳𝗿𝗲𝗲 𝗳𝗿𝗼𝗺 𝘁𝗵𝗲 𝗮𝗯𝘂𝘀𝗲 𝗼𝗳 𝗽𝗼𝘄𝗲𝗿. I’ve understood, and I’m ready to take the position. And when the result came, I was happy, and yet, I was thinking that it is a bigger arena to be elected in the highest level and carrying a university-wide responsibility. It was an opportunity to be an officer of the USC. \\\"\\r\\n\\r\\n​Ikinagagalak naming naging bahagi ka ng 𝐔𝐧𝐢𝐯𝐞𝐫𝐬𝐢𝐭𝐲 𝐒𝐭𝐮𝐝𝐞𝐧𝐭 𝐂𝐨𝐮𝐧𝐜𝐢𝐥. Ito ay isang tunay na patunay sa pandaigdigang kagalingan at kahusayan na iyong ipinamalas—at patuloy pang ipapamalas—para sa buong pamayanan ng DMMMSU.\\r\\n\\r\\n​𝑴𝒖𝒍𝒂 𝒔𝒂 𝑫𝑴𝑴𝑴𝑺𝑼 𝑴𝒊𝒅 𝑳𝒂 𝑼𝒏𝒊𝒐𝒏 𝑪𝒂𝒎𝒑𝒖𝒔, 𝒊𝒔𝒂𝒏𝒈 𝒎𝒂𝒍𝒖𝒈𝒐𝒅 𝒂𝒕 𝒎𝒂𝒊𝒏𝒊𝒕 𝒏𝒂 𝒑𝒂𝒈𝒃𝒂𝒕𝒊 𝒔𝒂 𝒏𝒂𝒈-𝒊𝒊𝒔𝒂𝒏𝒈 𝑱𝒐𝒆-𝒔𝒉𝒖𝒂 𝒏𝒈 𝑪𝑺𝑩𝑶, 𝑴𝒓. 𝑱𝒐𝒆 𝑳𝒆𝒊 𝒀𝒂𝒏𝒆 𝑷. 𝑺𝒐𝒕𝒆𝒍𝒐!\\r\\n\\r\\n**\\r\\nWords | S. Villacorta\\r\\nLayout | A. Galinato\\r\\n\\r\\n#MLUC_CSBOxCSC’26\\r\\n#DMMMSU_MLUC See less\",\"category\":\"mluc\",\"label\":\"MLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-07-09 16:08:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:09:19\",\"updated_at\":\"2026-08-24 16:09:19\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":31,\"post_id\":46,\"file_path\":\"uploads/posts/post_46_1c8cc6d853513ab0.jpg\",\"original_name\":\"769222623_1647493054046436_5259089146234490662_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:57:38\"}]}','Saved publication',1,'2026-09-01 13:57:38');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (78,45,2,'{\"post\":{\"id\":45,\"academic_year_id\":1,\"title\":\"#MLUCCSBOupdates | 𝐍𝐄𝐖 𝐅𝐀𝐂𝐄𝐒 𝐅𝐎𝐑 𝐀 𝐍𝐄𝐖 𝐇𝐎𝐑𝐈𝐙𝐎𝐍\",\"slug\":\"mluccsboupdates\",\"excerpt\":\"Last July 6, 2026, the Campus Student Body Organization (CSBO) officially finalized its leadership structure and administrative processes for the Academic Year 2026–2027.\\r\\n\\r\\n​The transition of leadership was formally sealed as the newly elected CSBO Officers took their oath of office before Chancellor Alvin R. Malicdem. In this solemn ceremony, the student leaders pledged their absolute dedication to serving the studentry and fiercely advocating for the rights, welfare, and interests of the entire campus population.\",\"content\":\"Last July 6, 2026, the Campus Student Body Organization (CSBO) officially finalized its leadership structure and administrative processes for the Academic Year 2026–2027.\\r\\n\\r\\n​The transition of leadership was formally sealed as the newly elected CSBO Officers took their oath of office before Chancellor Alvin R. Malicdem. In this solemn ceremony, the student leaders pledged their absolute dedication to serving the studentry and fiercely advocating for the rights, welfare, and interests of the entire campus population.\\r\\n\\r\\n𝐀𝐃𝐕𝐈𝐒𝐄𝐑: 𝐃𝐫. 𝐋𝐚𝐝𝐲 𝐌𝐚𝐞 𝐁. 𝐂𝐚𝐥𝐝𝐞𝐫𝐨𝐧\\r\\n𝐂𝐡𝐚𝐢𝐫𝐩𝐞𝐫𝐬𝐨𝐧: 𝐒𝐡𝐚𝐧𝐧𝐞𝐧 𝐂. 𝐕𝐢𝐥𝐥𝐚𝐜𝐨𝐫𝐭𝐚 (𝐂𝐎𝐌)\\r\\n𝐕𝐢𝐜𝐞 𝐂𝐡𝐚𝐢𝐫𝐩𝐞𝐫𝐬𝐨𝐧: 𝐉𝐞𝐫𝐞𝐦𝐢𝐚𝐡 𝐎. 𝐇𝐢𝐩𝐨𝐥 (𝐂𝐄)\\r\\n𝐒𝐞𝐜𝐫𝐞𝐭𝐚𝐫𝐲: 𝐉𝐨𝐞 𝐋𝐞𝐢 𝐘𝐚𝐧𝐞 𝐏. 𝐒𝐨𝐭𝐞𝐥𝐨 (𝐂𝐀𝐒)\\r\\n𝐓𝐫𝐞𝐚𝐬𝐮𝐫𝐞𝐫: 𝐌𝐚𝐫𝐢𝐚 𝐉𝐮𝐥𝐢𝐚𝐧𝐚 𝐅𝐫𝐚𝐧𝐜𝐞𝐬 𝐌. 𝐌𝐨𝐫𝐚𝐥𝐞𝐬 (𝐂𝐀𝐒)\\r\\n𝐀𝐮𝐝𝐢𝐭𝐨𝐫: 𝐉𝐞𝐫𝐢𝐜𝐡𝐨 𝐎. 𝐃𝐨𝐦𝐨𝐧𝐝𝐨𝐧 (𝐂𝐎𝐄)\\r\\n𝐁𝐮𝐬𝐢𝐧𝐞𝐬𝐬 𝐌𝐚𝐧𝐚𝐠𝐞𝐫: 𝐉𝐞𝐭𝐡𝐫𝐨 𝐋. 𝐆𝐚𝐧𝐧𝐚𝐝 (𝐂𝐎𝐓)\\r\\n𝐏.𝐑.𝐎.: 𝐊𝐂 𝐋𝐨𝐮𝐢𝐬𝐞 𝐑. 𝐂𝐚𝐥𝐮𝐬𝐜𝐮𝐬𝐢𝐧 (𝐂𝐈𝐓)\\r\\n𝐒𝐮𝐩𝐫𝐞𝐦𝐞 𝐆𝐨𝐯𝐞𝐫𝐧𝐨𝐫: 𝐑𝐞𝐠𝐠𝐢𝐞 𝐀𝐝𝐚𝐦 𝐌. 𝐀𝐛𝐮𝐛𝐨 (𝐂𝐎𝐌)\\r\\n\\r\\nThis marks the official commencement of a governance term anchored on accountability, institutional excellence, and proactive student advocacy. Armed with their mandate, this administration stands ready to foster a transparent and empowering environment for all students.\\r\\n\\r\\n**\\r\\nWords | S. Villacorta\\r\\n\\r\\n#MLUC_CSBOxCSC’26\\r\\n#DMMMSU_MLUC See less\",\"category\":\"mluc\",\"label\":\"MLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-07-08 17:00:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:07:57\",\"updated_at\":\"2026-08-24 16:07:57\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[]}','Snapshot before edit',1,'2026-09-01 13:57:58');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (79,45,3,'{\"post\":{\"id\":45,\"academic_year_id\":1,\"title\":\"#MLUCCSBOupdates | 𝐍𝐄𝐖 𝐅𝐀𝐂𝐄𝐒 𝐅𝐎𝐑 𝐀 𝐍𝐄𝐖 𝐇𝐎𝐑𝐈𝐙𝐎𝐍\",\"slug\":\"mluccsboupdates\",\"excerpt\":\"Last July 6, 2026, the Campus Student Body Organization (CSBO) officially finalized its leadership structure and administrative processes for the Academic Year 2026–2027.\\r\\n\\r\\n​The transition of leadership was formally sealed as the newly elected CSBO Officers took their oath of office before Chancellor Alvin R. Malicdem. In this solemn ceremony, the student leaders pledged their absolute dedication to serving the studentry and fiercely advocating for the rights, welfare, and interests of the entire campus population.\",\"content\":\"Last July 6, 2026, the Campus Student Body Organization (CSBO) officially finalized its leadership structure and administrative processes for the Academic Year 2026–2027.\\r\\n\\r\\n​The transition of leadership was formally sealed as the newly elected CSBO Officers took their oath of office before Chancellor Alvin R. Malicdem. In this solemn ceremony, the student leaders pledged their absolute dedication to serving the studentry and fiercely advocating for the rights, welfare, and interests of the entire campus population.\\r\\n\\r\\n𝐀𝐃𝐕𝐈𝐒𝐄𝐑: 𝐃𝐫. 𝐋𝐚𝐝𝐲 𝐌𝐚𝐞 𝐁. 𝐂𝐚𝐥𝐝𝐞𝐫𝐨𝐧\\r\\n𝐂𝐡𝐚𝐢𝐫𝐩𝐞𝐫𝐬𝐨𝐧: 𝐒𝐡𝐚𝐧𝐧𝐞𝐧 𝐂. 𝐕𝐢𝐥𝐥𝐚𝐜𝐨𝐫𝐭𝐚 (𝐂𝐎𝐌)\\r\\n𝐕𝐢𝐜𝐞 𝐂𝐡𝐚𝐢𝐫𝐩𝐞𝐫𝐬𝐨𝐧: 𝐉𝐞𝐫𝐞𝐦𝐢𝐚𝐡 𝐎. 𝐇𝐢𝐩𝐨𝐥 (𝐂𝐄)\\r\\n𝐒𝐞𝐜𝐫𝐞𝐭𝐚𝐫𝐲: 𝐉𝐨𝐞 𝐋𝐞𝐢 𝐘𝐚𝐧𝐞 𝐏. 𝐒𝐨𝐭𝐞𝐥𝐨 (𝐂𝐀𝐒)\\r\\n𝐓𝐫𝐞𝐚𝐬𝐮𝐫𝐞𝐫: 𝐌𝐚𝐫𝐢𝐚 𝐉𝐮𝐥𝐢𝐚𝐧𝐚 𝐅𝐫𝐚𝐧𝐜𝐞𝐬 𝐌. 𝐌𝐨𝐫𝐚𝐥𝐞𝐬 (𝐂𝐀𝐒)\\r\\n𝐀𝐮𝐝𝐢𝐭𝐨𝐫: 𝐉𝐞𝐫𝐢𝐜𝐡𝐨 𝐎. 𝐃𝐨𝐦𝐨𝐧𝐝𝐨𝐧 (𝐂𝐎𝐄)\\r\\n𝐁𝐮𝐬𝐢𝐧𝐞𝐬𝐬 𝐌𝐚𝐧𝐚𝐠𝐞𝐫: 𝐉𝐞𝐭𝐡𝐫𝐨 𝐋. 𝐆𝐚𝐧𝐧𝐚𝐝 (𝐂𝐎𝐓)\\r\\n𝐏.𝐑.𝐎.: 𝐊𝐂 𝐋𝐨𝐮𝐢𝐬𝐞 𝐑. 𝐂𝐚𝐥𝐮𝐬𝐜𝐮𝐬𝐢𝐧 (𝐂𝐈𝐓)\\r\\n𝐒𝐮𝐩𝐫𝐞𝐦𝐞 𝐆𝐨𝐯𝐞𝐫𝐧𝐨𝐫: 𝐑𝐞𝐠𝐠𝐢𝐞 𝐀𝐝𝐚𝐦 𝐌. 𝐀𝐛𝐮𝐛𝐨 (𝐂𝐎𝐌)\\r\\n\\r\\nThis marks the official commencement of a governance term anchored on accountability, institutional excellence, and proactive student advocacy. Armed with their mandate, this administration stands ready to foster a transparent and empowering environment for all students.\\r\\n\\r\\n**\\r\\nWords | S. Villacorta\\r\\n\\r\\n#MLUC_CSBOxCSC’26\\r\\n#DMMMSU_MLUC See less\",\"category\":\"mluc\",\"label\":\"MLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-07-08 17:00:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:07:57\",\"updated_at\":\"2026-08-24 16:07:57\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":32,\"post_id\":45,\"file_path\":\"uploads/posts/post_45_10f68e3dbd85a406.jpg\",\"original_name\":\"769000069_1647534080709000_633507435408768310_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:57:58\"}]}','Saved publication',1,'2026-09-01 13:57:58');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (80,50,12,'{\"post\":{\"id\":50,\"academic_year_id\":1,\"title\":\"Ninoy Aquino Day\",\"slug\":\"ninoy-aquino-day\",\"excerpt\":\"Sa paggunita natin sa Ninoy Aquino Day, ating binabalikan ang isang mahalagang bahagi ng kasaysayan ng Pilipinas ang tapang ng isang Pilipinong piniling ipaglaban ang kalayaan at demokrasya sa kabila ng panganib.\",\"content\":\"Sa paggunita natin sa Ninoy Aquino Day, ating binabalikan ang isang mahalagang bahagi ng kasaysayan ng Pilipinas ang tapang ng isang Pilipinong piniling ipaglaban ang kalayaan at demokrasya sa kabila ng panganib.\\r\\n\\r\\nAng buhay at sakripisyo ni Ninoy Aquino ay naging simbolo ng paninindigan para sa bayan. Ang kanyang pagkamatay ay hindi nagtapos sa kanyang laban; sa halip, nagmulat ito sa maraming Pilipino at nagbigay-lakas sa sambayanang manindigan para sa pagbabago, katarungan, at kalayaan.\\r\\n\\r\\nHigit sa pag-alala sa isang tao, ang araw na ito ay paalala sa kapangyarihan ng pagkakaisa. Ipinakita ng kasaysayan na kapag nagkaisa ang mga Pilipino at hindi natatakot ipahayag ang kanilang tinig, may kakayahan tayong harapin ang anumang hamon at ipaglaban ang nararapat.\\r\\n\\r\\nNawa’y magsilbing inspirasyon ang kanyang sakripisyo sa bawat Pilipino upang maging mapanindigan, makialam sa mga usaping panlipunan, at gamitin ang ating kalayaan nang may pananagutan.\\r\\n\\r\\nSa araw na ito, ating alalahanin si Ninoy Aquino hindi lamang bilang isang bayani ng nakaraan, kundi bilang paalala na ang tunay na pagmamahal sa bayan ay nakikita sa tapang na manindigan, sa malasakit sa kapwa, at sa patuloy na pag-asa para sa isang mas makatarungan at malayang Pilipinas.\\r\\n\\r\\nkatha ni P. E. Baustista\\r\\n\\r\\n#DMMMSUNLUC\\r\\n#nluccsbo\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-21 13:22:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:15:26\",\"updated_at\":\"2026-09-01 13:51:37\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":18,\"post_id\":50,\"file_path\":\"uploads/posts/post_50_0979174204dbcb89.jpg\",\"original_name\":\"781053443_1501952355282785_7552588831754086645_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:51:37\"}]}','Snapshot before edit',1,'2026-09-01 13:59:48');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (81,50,13,'{\"post\":{\"id\":50,\"academic_year_id\":1,\"title\":\"Ninoy Aquino Day\",\"slug\":\"ninoy-aquino-day\",\"excerpt\":\"Sa paggunita natin sa Ninoy Aquino Day, ating binabalikan ang isang mahalagang bahagi ng kasaysayan ng Pilipinas ang tapang ng isang Pilipinong piniling ipaglaban ang kalayaan at demokrasya sa kabila ng panganib.\",\"content\":\"Sa paggunita natin sa Ninoy Aquino Day, ating binabalikan ang isang mahalagang bahagi ng kasaysayan ng Pilipinas ang tapang ng isang Pilipinong piniling ipaglaban ang kalayaan at demokrasya sa kabila ng panganib.\\r\\n\\r\\nAng buhay at sakripisyo ni Ninoy Aquino ay naging simbolo ng paninindigan para sa bayan. Ang kanyang pagkamatay ay hindi nagtapos sa kanyang laban; sa halip, nagmulat ito sa maraming Pilipino at nagbigay-lakas sa sambayanang manindigan para sa pagbabago, katarungan, at kalayaan.\\r\\n\\r\\nHigit sa pag-alala sa isang tao, ang araw na ito ay paalala sa kapangyarihan ng pagkakaisa. Ipinakita ng kasaysayan na kapag nagkaisa ang mga Pilipino at hindi natatakot ipahayag ang kanilang tinig, may kakayahan tayong harapin ang anumang hamon at ipaglaban ang nararapat.\\r\\n\\r\\nNawa’y magsilbing inspirasyon ang kanyang sakripisyo sa bawat Pilipino upang maging mapanindigan, makialam sa mga usaping panlipunan, at gamitin ang ating kalayaan nang may pananagutan.\\r\\n\\r\\nSa araw na ito, ating alalahanin si Ninoy Aquino hindi lamang bilang isang bayani ng nakaraan, kundi bilang paalala na ang tunay na pagmamahal sa bayan ay nakikita sa tapang na manindigan, sa malasakit sa kapwa, at sa patuloy na pag-asa para sa isang mas makatarungan at malayang Pilipinas.\\r\\n\\r\\nkatha ni P. E. Baustista\\r\\n\\r\\n#DMMMSUNLUC\\r\\n#nluccsbo\",\"category\":\"nluc\",\"label\":\"NLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-21 13:22:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:15:26\",\"updated_at\":\"2026-09-01 13:59:48\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":18,\"post_id\":50,\"file_path\":\"uploads/posts/post_50_0979174204dbcb89.jpg\",\"original_name\":\"781053443_1501952355282785_7552588831754086645_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:51:37\"}]}','Saved publication',1,'2026-09-01 13:59:48');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (82,42,8,'{\"post\":{\"id\":42,\"academic_year_id\":1,\"title\":\"𝐀𝐃𝐕𝐈𝐒𝐎𝐑𝐘 | 𝐖𝐀𝐋𝐀𝐍𝐆 𝐏𝐀𝐒𝐎𝐊\",\"slug\":\"publication-4\",\"excerpt\":\"Pursuant to the Executive Order No. 43 and in view of the prevailing weather conditions, PGLU hereby announces the suspension of classes in all DMMMSU campuses on August 6, 2026.\\r\\n\\r\\nThe suspension covers all academic activities for the said date.\",\"content\":\"Pursuant to the Executive Order No. 43 and in view of the prevailing weather conditions, PGLU hereby announces the suspension of classes in all DMMMSU campuses on August 6, 2026.\\r\\n\\r\\nThe suspension covers all academic activities for the said date.\\r\\n\\r\\nStudents, faculty members, and personnel are advised to prioritize their safety and await further announcements through official university channels.\\r\\n\\r\\nPlease be guided accordingly.\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":1,\"is_university_featured\":1,\"status\":\"published\",\"published_at\":\"2026-08-05 19:37:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 15:58:57\",\"updated_at\":\"2026-09-01 13:10:22\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":22,\"post_id\":42,\"file_path\":\"uploads/posts/post_42_a70dd18c36026634.jpg\",\"original_name\":\"764845230_1528522139287585_374589350318008315_n (1).jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:53:01\"}]}','Snapshot before edit',1,'2026-09-01 14:01:21');
