INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (94,51,12,'{\"post\":{\"id\":51,\"academic_year_id\":1,\"title\":\"EXAM MODE: ON!\",\"slug\":\"exam-mode-on\",\"excerpt\":\"Isang ballpen, isang scratch, isang reviewer… at isang taong biglang nag-message ng “Good luck, love!” sana ol!\\r\\nHindi man kumpleto ang tulog, basta kumpleto ang gamit.\\r\\nHindi man handa ang utak, basta handa ang puso.\\r\\nAt kung wala talagang masagot sa exam—“Lord, ikaw na bahala.” 🙏😭\\r\\nPAPASA AKO! PAPASA KA! PAPASA TAYO!\\r\\nIpapasa ko para sa’yo. Ipapasa mo para sa’kin. Ipasa natin ’to, mga beh! 📖\\r\\nGood luck, NLUCians!\\r\\n#DMMMSUNLUC \\r\\n#nluccsbo\",\"content\":\"Isang ballpen, isang scratch, isang reviewer… at isang taong biglang nag-message ng “Good luck, love!” sana ol!\\r\\nHindi man kumpleto ang tulog, basta kumpleto ang gamit.\\r\\nHindi man handa ang utak, basta handa ang puso.\\r\\nAt kung wala talagang masagot sa exam—“Lord, ikaw na bahala.” 🙏😭\\r\\nPAPASA AKO! PAPASA KA! PAPASA TAYO!\\r\\nIpapasa ko para sa’yo. Ipapasa mo para sa’kin. Ipasa natin ’to, mga beh! 📖\\r\\nGood luck, NLUCians!\\r\\n#DMMMSUNLUC \\r\\n#nluccsbo\",\"category\":\"nluc\",\"label\":\"NLUC\",\"image\":null,\"is_featured\":1,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-23 22:17:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:18:05\",\"updated_at\":\"2026-09-01 13:51:03\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":17,\"post_id\":51,\"file_path\":\"uploads/posts/post_51_478548640c720999.jpg\",\"original_name\":\"784664975_1504026565075364_2903386929420344111_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:51:03\"}],\"videos\":[]}','Snapshot before edit',1,'2026-09-01 17:42:16');
