INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (110,52,1,'{\"post\":{\"id\":52,\"academic_year_id\":1,\"title\":\"University Student Council Welcomes New Students (Practice Page)\",\"slug\":\"university-student-council-welcomes-new-students-practice-page\",\"excerpt\":\"Welcome to a new academic year! The University Student Council is excited to welcome all students and looks forward to creating meaningful activities, programs, and opportunities throughout the year.\",\"content\":\"Welcome, Students! 🎉\\r\\n\\r\\nThe University Student Council warmly welcomes all students to another exciting and meaningful academic year!\\r\\n\\r\\nAs we begin a new chapter, the University Student Council is committed to representing the student body, promoting student welfare, and creating opportunities where every student can participate, share their ideas, and make a positive contribution to the university community.\\r\\n\\r\\nThroughout the academic year, the council will organize and support various activities, programs, campaigns, and initiatives designed to encourage student engagement and strengthen the connection between students and the university.\\r\\n\\r\\nStudents can look forward to upcoming events, leadership programs, academic and extracurricular activities, community initiatives, and other projects that aim to make campus life more enjoyable and meaningful.\\r\\n\\r\\nWe also encourage everyone to stay informed by regularly checking the official announcements and updates from the University Student Council. Important information regarding schedules, registration, activities, and other student-related matters will be posted through our official communication channels.\\r\\n\\r\\nYour participation and support are important in making these initiatives successful. Whether you choose to participate in an event, volunteer for a program, share your suggestions, or simply stay informed, every contribution helps build a stronger and more connected student community.\\r\\n\\r\\nIf you have concerns, suggestions, or ideas for future activities, we encourage you to reach out to the University Student Council. Your feedback can help us understand the needs of students and improve the programs and services we provide.\\r\\n\\r\\nLet us work together to make this academic year productive, inclusive, and memorable. With teamwork, enthusiasm, and active participation, we can create a campus community where every student feels heard, valued, and supported.\\r\\n\\r\\nWelcome back, everyone! We wish you a successful and fulfilling academic year. 💚\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-09-03 14:02:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-09-03 14:06:08\",\"updated_at\":\"2026-09-03 14:06:08\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[],\"videos\":[]}','Saved publication',1,'2026-09-03 14:06:08');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (111,52,2,'{\"post\":{\"id\":52,\"academic_year_id\":1,\"title\":\"University Student Council Welcomes New Students (Practice Page)\",\"slug\":\"university-student-council-welcomes-new-students-practice-page\",\"excerpt\":\"Welcome to a new academic year! The University Student Council is excited to welcome all students and looks forward to creating meaningful activities, programs, and opportunities throughout the year.\",\"content\":\"Welcome, Students! 🎉\\r\\n\\r\\nThe University Student Council warmly welcomes all students to another exciting and meaningful academic year!\\r\\n\\r\\nAs we begin a new chapter, the University Student Council is committed to representing the student body, promoting student welfare, and creating opportunities where every student can participate, share their ideas, and make a positive contribution to the university community.\\r\\n\\r\\nThroughout the academic year, the council will organize and support various activities, programs, campaigns, and initiatives designed to encourage student engagement and strengthen the connection between students and the university.\\r\\n\\r\\nStudents can look forward to upcoming events, leadership programs, academic and extracurricular activities, community initiatives, and other projects that aim to make campus life more enjoyable and meaningful.\\r\\n\\r\\nWe also encourage everyone to stay informed by regularly checking the official announcements and updates from the University Student Council. Important information regarding schedules, registration, activities, and other student-related matters will be posted through our official communication channels.\\r\\n\\r\\nYour participation and support are important in making these initiatives successful. Whether you choose to participate in an event, volunteer for a program, share your suggestions, or simply stay informed, every contribution helps build a stronger and more connected student community.\\r\\n\\r\\nIf you have concerns, suggestions, or ideas for future activities, we encourage you to reach out to the University Student Council. Your feedback can help us understand the needs of students and improve the programs and services we provide.\\r\\n\\r\\nLet us work together to make this academic year productive, inclusive, and memorable. With teamwork, enthusiasm, and active participation, we can create a campus community where every student feels heard, valued, and supported.\\r\\n\\r\\nWelcome back, everyone! We wish you a successful and fulfilling academic year. 💚\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-09-03 14:02:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-09-03 14:06:08\",\"updated_at\":\"2026-09-03 14:06:08\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[],\"videos\":[]}','Snapshot before edit',1,'2026-09-03 14:08:33');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (112,52,3,'{\"post\":{\"id\":52,\"academic_year_id\":1,\"title\":\"University Student Council Welcomes New Students (Practice Page)\",\"slug\":\"university-student-council-welcomes-new-students-practice-page\",\"excerpt\":\"Welcome to a new academic year! The University Student Council is excited to welcome all students and looks forward to creating meaningful activities, programs, and opportunities throughout the year.\",\"content\":\"Welcome, Students! 🎉\\r\\n\\r\\nThe University Student Council warmly welcomes all students to another exciting and meaningful academic year!\\r\\n\\r\\nAs we begin a new chapter, the University Student Council is committed to representing the student body, promoting student welfare, and creating opportunities where every student can participate, share their ideas, and make a positive contribution to the university community.\\r\\n\\r\\nThroughout the academic year, the council will organize and support various activities, programs, campaigns, and initiatives designed to encourage student engagement and strengthen the connection between students and the university.\\r\\n\\r\\nStudents can look forward to upcoming events, leadership programs, academic and extracurricular activities, community initiatives, and other projects that aim to make campus life more enjoyable and meaningful.\\r\\n\\r\\nWe also encourage everyone to stay informed by regularly checking the official announcements and updates from the University Student Council. Important information regarding schedules, registration, activities, and other student-related matters will be posted through our official communication channels.\\r\\n\\r\\nYour participation and support are important in making these initiatives successful. Whether you choose to participate in an event, volunteer for a program, share your suggestions, or simply stay informed, every contribution helps build a stronger and more connected student community.\\r\\n\\r\\nIf you have concerns, suggestions, or ideas for future activities, we encourage you to reach out to the University Student Council. Your feedback can help us understand the needs of students and improve the programs and services we provide.\\r\\n\\r\\nLet us work together to make this academic year productive, inclusive, and memorable. With teamwork, enthusiasm, and active participation, we can create a campus community where every student feels heard, valued, and supported.\\r\\n\\r\\nWelcome back, everyone! We wish you a successful and fulfilling academic year. 💚\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-09-03 14:02:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-09-03 14:06:08\",\"updated_at\":\"2026-09-03 14:06:08\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[],\"videos\":[{\"id\":1,\"post_id\":52,\"file_path\":\"uploads/posts/video_52_b7c6ee6e2f08158e.mp4\",\"original_name\":\"Genshin Impact 2026-06-01 07-47-18.mp4\",\"media_id\":null,\"mime_type\":\"video/mp4\",\"file_size\":112623146,\"sort_order\":0,\"created_at\":\"2026-09-03 14:08:33\"}]}','Saved publication',1,'2026-09-03 14:08:33');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (113,52,4,'{\"post\":{\"id\":52,\"academic_year_id\":1,\"title\":\"University Student Council Welcomes New Students (Practice Page)\",\"slug\":\"university-student-council-welcomes-new-students-practice-page\",\"excerpt\":\"Welcome to a new academic year! The University Student Council is excited to welcome all students and looks forward to creating meaningful activities, programs, and opportunities throughout the year.\",\"content\":\"Welcome, Students! 🎉\\r\\n\\r\\nThe University Student Council warmly welcomes all students to another exciting and meaningful academic year!\\r\\n\\r\\nAs we begin a new chapter, the University Student Council is committed to representing the student body, promoting student welfare, and creating opportunities where every student can participate, share their ideas, and make a positive contribution to the university community.\\r\\n\\r\\nThroughout the academic year, the council will organize and support various activities, programs, campaigns, and initiatives designed to encourage student engagement and strengthen the connection between students and the university.\\r\\n\\r\\nStudents can look forward to upcoming events, leadership programs, academic and extracurricular activities, community initiatives, and other projects that aim to make campus life more enjoyable and meaningful.\\r\\n\\r\\nWe also encourage everyone to stay informed by regularly checking the official announcements and updates from the University Student Council. Important information regarding schedules, registration, activities, and other student-related matters will be posted through our official communication channels.\\r\\n\\r\\nYour participation and support are important in making these initiatives successful. Whether you choose to participate in an event, volunteer for a program, share your suggestions, or simply stay informed, every contribution helps build a stronger and more connected student community.\\r\\n\\r\\nIf you have concerns, suggestions, or ideas for future activities, we encourage you to reach out to the University Student Council. Your feedback can help us understand the needs of students and improve the programs and services we provide.\\r\\n\\r\\nLet us work together to make this academic year productive, inclusive, and memorable. With teamwork, enthusiasm, and active participation, we can create a campus community where every student feels heard, valued, and supported.\\r\\n\\r\\nWelcome back, everyone! We wish you a successful and fulfilling academic year. 💚\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-09-03 14:02:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-09-03 14:06:08\",\"updated_at\":\"2026-09-03 14:06:08\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[],\"videos\":[]}','Snapshot before edit',1,'2026-09-03 14:21:16');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (114,52,5,'{\"post\":{\"id\":52,\"academic_year_id\":1,\"title\":\"University Student Council Welcomes New Students (Practice Page)\",\"slug\":\"university-student-council-welcomes-new-students-practice-page\",\"excerpt\":\"Welcome to a new academic year! The University Student Council is excited to welcome all students and looks forward to creating meaningful activities, programs, and opportunities throughout the year.\",\"content\":\"Welcome, Students! 🎉\\r\\n\\r\\nThe University Student Council warmly welcomes all students to another exciting and meaningful academic year!\\r\\n\\r\\nAs we begin a new chapter, the University Student Council is committed to representing the student body, promoting student welfare, and creating opportunities where every student can participate, share their ideas, and make a positive contribution to the university community.\\r\\n\\r\\nThroughout the academic year, the council will organize and support various activities, programs, campaigns, and initiatives designed to encourage student engagement and strengthen the connection between students and the university.\\r\\n\\r\\nStudents can look forward to upcoming events, leadership programs, academic and extracurricular activities, community initiatives, and other projects that aim to make campus life more enjoyable and meaningful.\\r\\n\\r\\nWe also encourage everyone to stay informed by regularly checking the official announcements and updates from the University Student Council. Important information regarding schedules, registration, activities, and other student-related matters will be posted through our official communication channels.\\r\\n\\r\\nYour participation and support are important in making these initiatives successful. Whether you choose to participate in an event, volunteer for a program, share your suggestions, or simply stay informed, every contribution helps build a stronger and more connected student community.\\r\\n\\r\\nIf you have concerns, suggestions, or ideas for future activities, we encourage you to reach out to the University Student Council. Your feedback can help us understand the needs of students and improve the programs and services we provide.\\r\\n\\r\\nLet us work together to make this academic year productive, inclusive, and memorable. With teamwork, enthusiasm, and active participation, we can create a campus community where every student feels heard, valued, and supported.\\r\\n\\r\\nWelcome back, everyone! We wish you a successful and fulfilling academic year. 💚\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-09-03 14:02:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-09-03 14:06:08\",\"updated_at\":\"2026-09-03 14:06:08\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":63,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_c7ea3037e9f808a9.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_12_11 pm.png\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":64,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_b191276744c7c1f2.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_12_30 pm.png\",\"media_id\":null,\"sort_order\":1,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":65,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_967a12e92a19dae6.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_12_52 pm.png\",\"media_id\":null,\"sort_order\":2,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":66,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_e8f01d4f9f43e1b2.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_17_13 pm.png\",\"media_id\":null,\"sort_order\":3,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":67,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_6916b29999375f2f.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_17_16 pm.png\",\"media_id\":null,\"sort_order\":4,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":68,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_de65ca60e0928795.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_30_23 pm.png\",\"media_id\":null,\"sort_order\":5,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":69,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_f67ce02c0c3155be.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_30_42 pm.png\",\"media_id\":null,\"sort_order\":6,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":70,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_36595096ffc1fe83.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_30_45 pm.png\",\"media_id\":null,\"sort_order\":7,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":71,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_dd458561afef28e6.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_30_47 pm.png\",\"media_id\":null,\"sort_order\":8,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":72,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_c8152516923411fc.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_31_22 pm.png\",\"media_id\":null,\"sort_order\":9,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":73,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_b55fd93cd8689b73.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_31_23 pm.png\",\"media_id\":null,\"sort_order\":10,\"created_at\":\"2026-09-03 14:21:16\"},{\"id\":74,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_025a7849628997e4.png\",\"original_name\":\"Genshin Impact 15_04_2026 8_31_25 pm.png\",\"media_id\":null,\"sort_order\":11,\"created_at\":\"2026-09-03 14:21:16\"}],\"videos\":[]}','Saved publication',1,'2026-09-03 14:21:16');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (115,52,6,'{\"post\":{\"id\":52,\"academic_year_id\":1,\"title\":\"University Student Council Welcomes New Students (Practice Page)\",\"slug\":\"university-student-council-welcomes-new-students-practice-page\",\"excerpt\":\"Welcome to a new academic year! The University Student Council is excited to welcome all students and looks forward to creating meaningful activities, programs, and opportunities throughout the year.\",\"content\":\"Welcome, Students! 🎉\\r\\n\\r\\nThe University Student Council warmly welcomes all students to another exciting and meaningful academic year!\\r\\n\\r\\nAs we begin a new chapter, the University Student Council is committed to representing the student body, promoting student welfare, and creating opportunities where every student can participate, share their ideas, and make a positive contribution to the university community.\\r\\n\\r\\nThroughout the academic year, the council will organize and support various activities, programs, campaigns, and initiatives designed to encourage student engagement and strengthen the connection between students and the university.\\r\\n\\r\\nStudents can look forward to upcoming events, leadership programs, academic and extracurricular activities, community initiatives, and other projects that aim to make campus life more enjoyable and meaningful.\\r\\n\\r\\nWe also encourage everyone to stay informed by regularly checking the official announcements and updates from the University Student Council. Important information regarding schedules, registration, activities, and other student-related matters will be posted through our official communication channels.\\r\\n\\r\\nYour participation and support are important in making these initiatives successful. Whether you choose to participate in an event, volunteer for a program, share your suggestions, or simply stay informed, every contribution helps build a stronger and more connected student community.\\r\\n\\r\\nIf you have concerns, suggestions, or ideas for future activities, we encourage you to reach out to the University Student Council. Your feedback can help us understand the needs of students and improve the programs and services we provide.\\r\\n\\r\\nLet us work together to make this academic year productive, inclusive, and memorable. With teamwork, enthusiasm, and active participation, we can create a campus community where every student feels heard, valued, and supported.\\r\\n\\r\\nWelcome back, everyone! We wish you a successful and fulfilling academic year. 💚\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-09-03 14:02:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-09-03 14:06:08\",\"updated_at\":\"2026-09-03 14:06:08\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[],\"videos\":[]}','Snapshot before edit',1,'2026-09-03 14:36:22');
