INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (117,52,8,'{\"post\":{\"id\":52,\"academic_year_id\":1,\"title\":\"University Student Council Welcomes New Students (Practice Page)\",\"slug\":\"university-student-council-welcomes-new-students-practice-page\",\"excerpt\":\"Welcome to a new academic year! The University Student Council is excited to welcome all students and looks forward to creating meaningful activities, programs, and opportunities throughout the year.\",\"content\":\"Welcome, Students! 🎉\\r\\n\\r\\nThe University Student Council warmly welcomes all students to another exciting and meaningful academic year!\\r\\n\\r\\nAs we begin a new chapter, the University Student Council is committed to representing the student body, promoting student welfare, and creating opportunities where every student can participate, share their ideas, and make a positive contribution to the university community.\\r\\n\\r\\nThroughout the academic year, the council will organize and support various activities, programs, campaigns, and initiatives designed to encourage student engagement and strengthen the connection between students and the university.\\r\\n\\r\\nStudents can look forward to upcoming events, leadership programs, academic and extracurricular activities, community initiatives, and other projects that aim to make campus life more enjoyable and meaningful.\\r\\n\\r\\nWe also encourage everyone to stay informed by regularly checking the official announcements and updates from the University Student Council. Important information regarding schedules, registration, activities, and other student-related matters will be posted through our official communication channels.\\r\\n\\r\\nYour participation and support are important in making these initiatives successful. Whether you choose to participate in an event, volunteer for a program, share your suggestions, or simply stay informed, every contribution helps build a stronger and more connected student community.\\r\\n\\r\\nIf you have concerns, suggestions, or ideas for future activities, we encourage you to reach out to the University Student Council. Your feedback can help us understand the needs of students and improve the programs and services we provide.\\r\\n\\r\\nLet us work together to make this academic year productive, inclusive, and memorable. With teamwork, enthusiasm, and active participation, we can create a campus community where every student feels heard, valued, and supported.\\r\\n\\r\\nWelcome back, everyone! We wish you a successful and fulfilling academic year. 💚\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-09-03 14:02:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-09-03 14:06:08\",\"updated_at\":\"2026-09-03 14:06:08\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":76,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_979d6e7e1b648c47.jpg\",\"original_name\":\"761747527_1526379522835180_6287043047617718657_n.jpg\",\"media_id\":null,\"sort_order\":1,\"created_at\":\"2026-09-03 14:36:22\"},{\"id\":77,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_981f6f5deafba6fd.jpg\",\"original_name\":\"769000069_1647534080709000_633507435408768310_n.jpg\",\"media_id\":null,\"sort_order\":2,\"created_at\":\"2026-09-03 14:36:22\"}],\"videos\":[]}','Snapshot before edit',1,'2026-09-03 14:36:45');
INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (118,52,9,'{\"post\":{\"id\":52,\"academic_year_id\":1,\"title\":\"University Student Council Welcomes New Students (Practice Page)\",\"slug\":\"university-student-council-welcomes-new-students-practice-page\",\"excerpt\":\"Welcome to a new academic year! The University Student Council is excited to welcome all students and looks forward to creating meaningful activities, programs, and opportunities throughout the year.\",\"content\":\"Welcome, Students! 🎉\\r\\n\\r\\nThe University Student Council warmly welcomes all students to another exciting and meaningful academic year!\\r\\n\\r\\nAs we begin a new chapter, the University Student Council is committed to representing the student body, promoting student welfare, and creating opportunities where every student can participate, share their ideas, and make a positive contribution to the university community.\\r\\n\\r\\nThroughout the academic year, the council will organize and support various activities, programs, campaigns, and initiatives designed to encourage student engagement and strengthen the connection between students and the university.\\r\\n\\r\\nStudents can look forward to upcoming events, leadership programs, academic and extracurricular activities, community initiatives, and other projects that aim to make campus life more enjoyable and meaningful.\\r\\n\\r\\nWe also encourage everyone to stay informed by regularly checking the official announcements and updates from the University Student Council. Important information regarding schedules, registration, activities, and other student-related matters will be posted through our official communication channels.\\r\\n\\r\\nYour participation and support are important in making these initiatives successful. Whether you choose to participate in an event, volunteer for a program, share your suggestions, or simply stay informed, every contribution helps build a stronger and more connected student community.\\r\\n\\r\\nIf you have concerns, suggestions, or ideas for future activities, we encourage you to reach out to the University Student Council. Your feedback can help us understand the needs of students and improve the programs and services we provide.\\r\\n\\r\\nLet us work together to make this academic year productive, inclusive, and memorable. With teamwork, enthusiasm, and active participation, we can create a campus community where every student feels heard, valued, and supported.\\r\\n\\r\\nWelcome back, everyone! We wish you a successful and fulfilling academic year. 💚\",\"category\":\"usc\",\"label\":\"USC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-09-03 14:02:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-09-03 14:06:08\",\"updated_at\":\"2026-09-03 14:06:08\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":76,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_979d6e7e1b648c47.jpg\",\"original_name\":\"761747527_1526379522835180_6287043047617718657_n.jpg\",\"media_id\":null,\"sort_order\":1,\"created_at\":\"2026-09-03 14:36:22\"},{\"id\":77,\"post_id\":52,\"file_path\":\"uploads/posts/post_52_981f6f5deafba6fd.jpg\",\"original_name\":\"769000069_1647534080709000_633507435408768310_n.jpg\",\"media_id\":null,\"sort_order\":2,\"created_at\":\"2026-09-03 14:36:22\"}],\"videos\":[]}','Saved publication',1,'2026-09-03 14:36:45');
