INSERT INTO `post_revisions` (`id`,`post_id`,`revision_no`,`snapshot_json`,`change_note`,`created_by`,`created_at`) VALUES (145,48,4,'{\"post\":{\"id\":48,\"academic_year_id\":1,\"title\":\"Pens up! Papers out! 📝\",\"slug\":\"pens-up-papers-out\",\"excerpt\":\"To all DMMMSU-NLUC students taking the Midterm Examinations — you’ve studied hard, you’ve prepared, and now it’s your time to shine! 💪\\r\\n\\r\\nFrom the DMMMSU-NLUC Campus Student Body Organization, we’re sending you all the good vibes and encouragement as you take your Midterm Examinations.\\r\\nGood luck! Do your best and trust the process.\\r\\n\\r\\nGOOD LUCK, NLUcians! We’re rooting for you! 💚\\r\\n\\r\\n#DMMMSUNLUC\\r\\n#CSBO\\r\\n#Midterms2026\",\"content\":\"\",\"category\":\"nluc\",\"label\":\"NLUC\",\"image\":null,\"is_featured\":0,\"is_university_featured\":0,\"status\":\"published\",\"published_at\":\"2026-08-16 20:43:00\",\"scheduled_at\":null,\"review_note\":\"\",\"published_by\":1,\"scheduled_by\":null,\"created_at\":\"2026-08-24 16:13:21\",\"updated_at\":\"2026-08-24 16:13:21\",\"deleted_at\":null,\"deleted_by\":null},\"images\":[{\"id\":20,\"post_id\":48,\"file_path\":\"uploads/posts/post_48_d7a38a1cb8c4de00.jpg\",\"original_name\":\"774411978_1497741259037228_2051844440996177659_n.jpg\",\"media_id\":null,\"sort_order\":0,\"created_at\":\"2026-09-01 13:52:13\"}],\"videos\":[]}','Snapshot before edit',1,'2026-09-03 16:05:24');
