DROP TABLE IF EXISTS `concerns`;
CREATE TABLE `concerns` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `reference_code` varchar(40) NOT NULL,
  `campus` varchar(50) NOT NULL,
  `college` varchar(180) DEFAULT NULL,
  `source_portal` varchar(10) NOT NULL DEFAULT 'USC',
  `assigned_scope` varchar(10) NOT NULL DEFAULT 'USC',
  `academic_year_id` int(11) DEFAULT NULL,
  `concern_type` varchar(50) NOT NULL,
  `student_name` varchar(150) DEFAULT NULL,
  `student_id` varchar(80) DEFAULT NULL,
  `subject` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `anonymous` tinyint(1) DEFAULT 0,
  `sensitivity` varchar(20) NOT NULL DEFAULT 'standard',
  `status` enum('Submitted','Received','Under Review','Referred','In Progress','Action Taken','Resolved','Closed') NOT NULL DEFAULT 'Submitted',
  `priority` varchar(20) NOT NULL DEFAULT 'Normal',
  `assigned_to` int(11) DEFAULT NULL,
  `due_at` datetime DEFAULT NULL,
  `follow_up_at` datetime DEFAULT NULL,
  `first_response_at` datetime DEFAULT NULL,
  `last_public_update_at` datetime DEFAULT NULL,
  `admin_note` text DEFAULT NULL,
  `internal_note` text DEFAULT NULL,
  `resolution_summary` text DEFAULT NULL,
  `escalation_reason` text DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `retention_until` date DEFAULT NULL,
  `privacy_review_status` varchar(30) NOT NULL DEFAULT 'pending',
  `privacy_reviewed_at` datetime DEFAULT NULL,
  `privacy_reviewed_by` int(11) DEFAULT NULL,
  `sensitive_view_count` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `reference_code` (`reference_code`),
  KEY `idx_concerns_source_portal` (`source_portal`),
  KEY `idx_concerns_assigned_scope` (`assigned_scope`),
  KEY `idx_concern_work_queue` (`assigned_scope`,`status`,`due_at`,`priority`),
  KEY `idx_concern_assignee` (`assigned_to`,`status`,`due_at`),
  KEY `idx_concern_created` (`created_at`),
  KEY `idx_concern_privacy_review` (`privacy_review_status`,`retention_until`),
  KEY `idx_concern_status_created` (`status`,`created_at`),
  KEY `idx_concern_followup` (`status`,`follow_up_at`),
  KEY `usc_fk_concern_privacy_reviewer` (`privacy_reviewed_by`),
  KEY `idx_concerns_academic_year` (`academic_year_id`,`status`,`created_at`),
  CONSTRAINT `fk_concerns_assigned_to` FOREIGN KEY (`assigned_to`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `usc_fk_concern_privacy_reviewer` FOREIGN KEY (`privacy_reviewed_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL,
  CONSTRAINT `usc_fk_concerns_academic_year` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

