DROP TABLE IF EXISTS `hero_slides`;
CREATE TABLE `hero_slides` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `portal_code` varchar(10) NOT NULL DEFAULT 'USC',
  `theme` varchar(30) NOT NULL DEFAULT 'green',
  `eyebrow` varchar(160) NOT NULL,
