  `description` text NOT NULL,
  `primary_label` varchar(80) DEFAULT NULL,
  `primary_url` varchar(255) DEFAULT NULL,
  `secondary_label` varchar(80) DEFAULT NULL,
  `secondary_url` varchar(255) DEFAULT NULL,
  `button_mode` varchar(20) NOT NULL DEFAULT 'both',
  `panel_type` varchar(30) NOT NULL DEFAULT 'card',
  `panel_kicker` varchar(80) DEFAULT NULL,
  `panel_status` varchar(40) DEFAULT NULL,
  `panel_title` varchar(180) DEFAULT NULL,
  `panel_description` text DEFAULT NULL,
  `panel_image` varchar(255) DEFAULT NULL,
  `panel_media_id` int(11) DEFAULT NULL,
  `background_image` varchar(255) DEFAULT NULL,
  `background_media_id` int(11) DEFAULT NULL,
  `background_position_x` tinyint(3) unsigned NOT NULL DEFAULT 50,
  `background_position_y` tinyint(3) unsigned NOT NULL DEFAULT 50,
  `display_mode` varchar(30) NOT NULL DEFAULT 'standard',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_hero_portal_order` (`portal_code`,`sort_order`,`id`),
  KEY `fk_hero_panel_media` (`panel_media_id`),
  KEY `fk_hero_background_media` (`background_media_id`),
  CONSTRAINT `fk_hero_background_media` FOREIGN KEY (`background_media_id`) REFERENCES `media_library` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_hero_panel_media` FOREIGN KEY (`panel_media_id`) REFERENCES `media_library` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `media_library`;
CREATE TABLE `media_library` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `file_path` varchar(255) NOT NULL,
  `thumbnail_path` varchar(255) DEFAULT NULL,
  `original_name` varchar(255) DEFAULT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `file_size` int(11) DEFAULT NULL,
  `width` int(11) DEFAULT NULL,
  `height` int(11) DEFAULT NULL,
  `sha256` char(64) DEFAULT NULL,
  `last_verified_at` datetime DEFAULT NULL,
  `optimized_at` datetime DEFAULT NULL,
  `alt_text` varchar(255) DEFAULT NULL,
  `uploaded_by` int(11) DEFAULT NULL,
  `campus` varchar(20) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_media_sha256` (`sha256`),
  KEY `fk_media_uploaded_by` (`uploaded_by`),
  KEY `fk_media_deleted_by` (`deleted_by`),
  KEY `idx_media_optimized` (`optimized_at`,`created_at`),
  CONSTRAINT `fk_media_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_media_uploaded_by` FOREIGN KEY (`uploaded_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `notification_email_outbox`;
CREATE TABLE `notification_email_outbox` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `admin_id` int(11) DEFAULT NULL,
  `concern_id` int(11) DEFAULT NULL,
  `recipient` varchar(190) NOT NULL,
  `subject` varchar(190) NOT NULL,
  `body` text NOT NULL,
  `category` varchar(40) NOT NULL DEFAULT 'general',
  `status` varchar(30) NOT NULL DEFAULT 'queued',
  `attempts` int(11) NOT NULL DEFAULT 0,
  `last_error` varchar(500) DEFAULT NULL,
  `sent_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_email_outbox` (`status`,`created_at`),
  KEY `idx_email_outbox_admin` (`admin_id`,`created_at`),
  KEY `idx_email_outbox_concern` (`concern_id`,`created_at`),
  CONSTRAINT `usc_fk_email_outbox_admin` FOREIGN KEY (`admin_id`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `usc_fk_email_outbox_concern` FOREIGN KEY (`concern_id`) REFERENCES `concerns` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `officers`;
CREATE TABLE `officers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `academic_year_id` int(11) DEFAULT NULL,
  `portal_code` varchar(10) NOT NULL DEFAULT 'USC',
  `full_name` varchar(150) NOT NULL,
  `position_title` varchar(150) NOT NULL,
  `office_name` varchar(150) DEFAULT NULL,
  `email` varchar(180) DEFAULT NULL,
  `photo_path` varchar(255) DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `is_archived` tinyint(1) NOT NULL DEFAULT 0,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_officers_scope_year` (`portal_code`,`academic_year_id`,`is_archived`,`sort_order`),
  KEY `usc_fk_officers_year` (`academic_year_id`),
  KEY `usc_fk_officers_created_by` (`created_by`),
  CONSTRAINT `usc_fk_officers_created_by` FOREIGN KEY (`created_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `usc_fk_officers_year` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `post_images`;
CREATE TABLE `post_images` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `post_id` int(11) NOT NULL,
  `file_path` varchar(255) NOT NULL,
  `original_name` varchar(255) DEFAULT NULL,
  `media_id` int(11) DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_post_images_post_id` (`post_id`),
  KEY `idx_post_images_media_id` (`media_id`),
  CONSTRAINT `fk_post_images_media` FOREIGN KEY (`media_id`) REFERENCES `media_library` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_post_images_post` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `post_revisions`;
CREATE TABLE `post_revisions` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `post_id` int(11) NOT NULL,
  `revision_no` int(11) NOT NULL,
  `snapshot_json` longtext NOT NULL,
  `change_note` varchar(255) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_post_revision` (`post_id`,`revision_no`),
  KEY `idx_post_revision_created` (`post_id`,`created_at`),
  KEY `usc_fk_post_revisions_admin` (`created_by`),
  CONSTRAINT `usc_fk_post_revisions_admin` FOREIGN KEY (`created_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL,
  CONSTRAINT `usc_fk_post_revisions_post` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=147 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `post_videos`;
CREATE TABLE `post_videos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `post_id` int(11) NOT NULL,
  `file_path` varchar(255) NOT NULL,
  `original_name` varchar(255) DEFAULT NULL,
  `media_id` int(11) DEFAULT NULL,
  `mime_type` varchar(100) NOT NULL,
  `file_size` bigint(20) unsigned NOT NULL DEFAULT 0,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_post_videos_post_id` (`post_id`),
  KEY `idx_post_videos_media_id` (`media_id`),
  CONSTRAINT `usc_fk_post_videos_media` FOREIGN KEY (`media_id`) REFERENCES `media_library` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `usc_fk_post_videos_post` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `posts`;
CREATE TABLE `posts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `academic_year_id` int(11) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(191) DEFAULT NULL,
  `excerpt` text DEFAULT NULL,
  `content` longtext DEFAULT NULL,
  `category` enum('usc','nluc','mluc','sluc','ous') NOT NULL DEFAULT 'usc',
  `label` varchar(100) DEFAULT 'USC',
  `image` varchar(255) DEFAULT NULL,
  `is_featured` tinyint(1) DEFAULT 0,
  `is_university_featured` tinyint(1) NOT NULL DEFAULT 0,
  `status` enum('draft','review','published','archived') NOT NULL DEFAULT 'published',
  `published_at` datetime DEFAULT current_timestamp(),
  `scheduled_at` datetime DEFAULT NULL,
  `review_note` text DEFAULT NULL,
  `published_by` int(11) DEFAULT NULL,
  `scheduled_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_posts_slug` (`slug`),
  KEY `idx_posts_public_schedule` (`status`,`scheduled_at`,`published_at`,`category`),
  KEY `idx_posts_category_status_slug` (`category`,`status`,`slug`),
  KEY `fk_posts_deleted_by` (`deleted_by`),
  KEY `usc_fk_posts_published_by` (`published_by`),
  KEY `usc_fk_posts_scheduled_by` (`scheduled_by`),
  KEY `idx_posts_status_category_date` (`status`,`category`,`published_at`),
  KEY `idx_posts_academic_year` (`academic_year_id`,`status`,`published_at`),
  KEY `idx_posts_university_featured` (`is_university_featured`,`status`,`published_at`),
  CONSTRAINT `fk_posts_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `usc_fk_posts_academic_year` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `usc_fk_posts_published_by` FOREIGN KEY (`published_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL,
  CONSTRAINT `usc_fk_posts_scheduled_by` FOREIGN KEY (`scheduled_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `privacy_access_log`;
CREATE TABLE `privacy_access_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `admin_id` int(11) DEFAULT NULL,
  `concern_id` int(11) NOT NULL,
  `action` varchar(60) NOT NULL,
  `purpose` varchar(255) DEFAULT NULL,
  `ip_address` varchar(64) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_privacy_concern` (`concern_id`,`created_at`),
  KEY `idx_privacy_admin` (`admin_id`,`created_at`),
  CONSTRAINT `fk_privacy_admin` FOREIGN KEY (`admin_id`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_privacy_concern` FOREIGN KEY (`concern_id`) REFERENCES `concerns` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `role_permission_overrides`;
CREATE TABLE `role_permission_overrides` (
  `role` varchar(40) NOT NULL,
  `permission` varchar(100) NOT NULL,
  `allowed` tinyint(1) NOT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`role`,`permission`),
  KEY `usc_fk_role_permission_updated_by` (`updated_by`),
  CONSTRAINT `usc_fk_role_permission_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `schema_migrations`;
CREATE TABLE `schema_migrations` (
  `version` varchar(30) NOT NULL,
  `description` varchar(255) NOT NULL,
  `safety_backup_filename` varchar(255) DEFAULT NULL,
  `applied_by` int(11) DEFAULT NULL,
  `duration_ms` int(11) DEFAULT NULL,
  `result` varchar(30) NOT NULL DEFAULT 'applied',
  `applied_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`version`),
  KEY `fk_migrations_applied_by` (`applied_by`),
  CONSTRAINT `fk_migrations_applied_by` FOREIGN KEY (`applied_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `submission_rate_limits`;
CREATE TABLE `submission_rate_limits` (
  `bucket_key` char(64) NOT NULL,
  `admin_id` int(11) DEFAULT NULL,
  `attempts` int(11) NOT NULL DEFAULT 0,
  `window_started_at` datetime NOT NULL,
  `last_attempt_at` datetime NOT NULL,
  `blocked_until` datetime DEFAULT NULL,
  PRIMARY KEY (`bucket_key`),
  KEY `idx_rate_limit_admin` (`admin_id`,`last_attempt_at`),
  CONSTRAINT `usc_fk_rate_limit_admin` FOREIGN KEY (`admin_id`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `system_settings`;
CREATE TABLE `system_settings` (
  `setting_key` varchar(100) NOT NULL,
  `setting_value` text DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`setting_key`),
  KEY `fk_settings_updated_by` (`updated_by`),
  CONSTRAINT `fk_settings_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `admins` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS=1;
